window.__Q=window.__Q||{};window.__Q["clin/5/B1"]=[{"q":"染色特性有异染颗粒的是","o":["大肠埃希菌","结核分枝杆菌","白喉棒状杆菌","破伤风梭菌","流感嗜血杆菌"],"a":2,"e":"白喉棒状杆菌用美蓝或奈瑟染色时菌体着色不均，两端浓染形成异染颗粒，主要由多偏磷酸盐构成，是该菌形态学鉴定的重要依据。结核分枝杆菌的特征是抗酸性，须抗酸染色显红色杆菌；破伤风梭菌的特征是顶端圆形芽胞使菌体呈鼓槌状。大肠埃希菌与流感嗜血杆菌均为革兰阴性小杆菌，无此颗粒"},{"q":"能进行芽孢染色的细菌是","o":["大肠埃希菌","结核分枝杆菌","白喉棒状杆菌","破伤风梭菌","流感嗜血杆菌"],"a":3,"e":"破伤风梭菌属厌氧芽胞梭菌，芽胞圆形、位于菌体顶端且直径大于菌体，须经芽胞染色（孔雀绿加热初染、复红复染）才能显示，芽胞呈绿色、繁殖体呈红色。白喉棒状杆菌无芽胞，靠异染颗粒鉴定；结核分枝杆菌靠抗酸染色。大肠埃希菌、流感嗜血杆菌为革兰阴性菌，均不形成芽胞"},{"q":"抗酸染色阳性的细菌是","o":["大肠埃希菌","结核分枝杆菌","白喉棒状杆菌","破伤风梭菌","流感嗜血杆菌"],"a":1,"e":"结核分枝杆菌细胞壁富含分枝菌酸，苯酚复红着色后能抵抗3%盐酸乙醇脱色而呈红色，为抗酸染色阳性。白喉棒状杆菌革兰阳性，可见异染颗粒，以美蓝染色观察；破伤风梭菌以芽胞染色鉴定。大肠埃希菌与流感嗜血杆菌为革兰阴性，抗酸染色阴性，复染后呈蓝色"},{"q":"致病菌由局部进入血流，但未在血流中生长繁殖，只是短暂的一过性通过血循环到达体内适宜部位后再进行繁殖而致病。称之为","o":["毒血症","内毒素血症","菌血症","败血症","脓毒血症"],"a":2,"e":"菌血症指致病菌由局部侵入血流但不在血中繁殖，仅短暂通过血流到达适宜部位再繁殖致病，伤寒早期即属此期，血培养可检出病原菌。毒血症是细菌留在局部、只有外毒素入血致病；败血症为细菌入血并大量繁殖产生毒性产物，伴高热、瘀斑与肝脾大。内毒素血症见于革兰阴性菌在血中崩解释放内毒素；脓毒血症须有化脓病灶与转移性脓肿"},{"q":"致病菌侵入血流后，在其中大量繁殖并产生毒性产物，引起全身性中毒症状。称之为","o":["毒血症","内毒素血症","菌血症","败血症","脓毒血症"],"a":3,"e":"败血症指病原菌侵入血流并在其中大量繁殖、产生毒性产物，引起高热、皮肤黏膜瘀斑、肝脾大等全身中毒症状，鼠疫耶尔森菌、炭疽芽胞杆菌均可引起。菌血症只在血中短暂通过、不繁殖；毒血症为细菌不入血而外毒素入血；内毒素血症由革兰阴性菌崩解释放内毒素所致；脓毒血症须伴化脓性病灶与转移性脓肿"},{"q":"致病菌侵入宿主体内后，只在机体局部生长繁殖，不进入血液循环，但其产生的外毒素入血，经血液到达易感的组织和细胞引起特殊的毒性症状。称之为","o":["毒血症","内毒素血症","菌血症","败血症","脓毒血症"],"a":0,"e":"毒血症指致病菌只在局部生长繁殖、不进入血流，其产生的外毒素入血并到达易感组织细胞引起特殊症状，白喉、破伤风即属此类。菌血症是细菌短暂通过血流；败血症为细菌入血后大量繁殖并产生毒性产物；内毒素血症由革兰阴性菌释放内毒素引起；脓毒血症伴化脓病灶与转移性脓肿"},{"q":"需要抗体协助通过ADCC杀伤病毒感染细胞的是","o":["B细胞","Th1细胞","NK细胞","CD8＋CTL","MΦ"],"a":2,"e":"ADCC由IgG的Fc段与NK细胞表面FcγRⅢ结合，使NK细胞定向裂解被抗体包被的病毒感染细胞，NK细胞本身无抗原特异性。CD8+CTL靠TCR识别MHCⅠ类分子提呈的病毒肽段直接杀伤靶细胞；Th1细胞以分泌IFN-γ等细胞因子辅助；MΦ主要吞噬清除；B细胞负责产生抗体"},{"q":"能分泌细胞因子强化NK细胞和MΦ杀伤功能的是","o":["B细胞","Th1细胞","NK细胞","CD8＋CTL","MΦ"],"a":1,"e":"CD4+Th1细胞分泌IL-2、IFN-γ、TNF-α，其中IFN-γ活化巨噬细胞，增强其对胞内病原微生物的杀伤，是抗胞内菌与病毒感染的重要辅助细胞。CD8+CTL以直接杀伤靶细胞为主；NK细胞属固有免疫杀伤细胞；B细胞产生抗体；MΦ是受细胞因子活化的一方"},{"q":"具有Fc受体，可被某些病毒感染成为扩散媒介的是","o":["B细胞","Th1细胞","NK细胞","CD8＋CTL","MΦ"],"a":4,"e":"单核巨噬细胞表面表达FcγR，可结合IgG型免疫复合物。登革病毒再次感染时，亚中和浓度抗体与病毒形成的复合物经Fc受体进入单核巨噬细胞，反而增强感染，即抗体依赖性增强作用，巨噬细胞因此成为病毒扩散的媒介。NK细胞虽有FcγR介导ADCC，但以杀伤为主；B细胞、Th1细胞与CTL不承担此扩散作用"},{"q":"识别MHCⅠ类分子特异性杀伤病毒感染细胞的是","o":["B细胞","Th1细胞","NK细胞","CD8＋CTL","MΦ"],"a":3,"e":"CD8+CTL的TCR识别靶细胞MHCⅠ类分子提呈的病毒抗原肽，经穿孔素、颗粒酶途径裂解感染细胞，受MHCⅠ类分子限制，是终止病毒感染的主要效应机制。Th1细胞识别MHCⅡ类分子提呈的抗原，以细胞因子发挥作用；NK细胞杀伤不受MHC限制、无抗原特异性；B细胞与MΦ不承担特异性杀伤"},{"q":"肥达反应O凝集效价低，H凝集效价高说明","o":["肠热症可能性大","肠热症可能性小","肠热症早期或交叉反应","预防接种或回忆反应","细胞免疫功能低下"],"a":3,"e":"O抗体为IgM，出现早、消失快；H抗体为IgG，出现晚、持续久。O效价不高而H效价高提示既往接触过抗原，多为预防接种或非特异性回忆反应，而非现症感染。O、H均升高才提示肠热症可能性大；O高H低为感染早期或与其他沙门菌O抗原交叉反应；两者均低则患病可能性小"},{"q":"肥达反应O凝集效价高，H凝集效价低说明","o":["肠热症可能性大","肠热症可能性小","肠热症早期或交叉反应","预防接种或回忆反应","细胞免疫功能低下"],"a":2,"e":"O抗体为IgM，出现早、消失快，H抗体为IgG，出现晚、持续久。O效价高而H不高，见于感染早期抗体尚未转换，或与伤寒沙门菌O抗原有交叉反应的其他沙门菌感染。O、H均高提示肠热症可能性大；O低H高为预防接种或回忆反应；两者均低则患病可能性小"},{"q":"肥达试验O、H凝集效价均高于正常说明","o":["肠热症可能性大","肠热症可能性小","肠热症早期或交叉反应","预防接种或回忆反应","细胞免疫功能低下"],"a":0,"e":"肥达试验中O抗体为IgM、H抗体为IgG，两者效价均超过正常值（O≥1:80、H≥1:160）提示近期有伤寒沙门菌感染，肠热症可能性大，双份血清4倍升高更有意义。O高H低为感染早期或交叉反应；O低H高为预防接种或回忆反应；两者均低则患病可能性小；该试验与细胞免疫功能无关"},{"q":"由肺炎支原体引起的疾病是","o":["非淋球菌性尿道炎","猫抓病","足菌肿","原发性非典型性肺炎","莱姆病"],"a":3,"e":"肺炎支原体经飞沫传播，黏附于呼吸道上皮并产生过氧化氢等，引起间质性肺炎，临床称原发性非典型性肺炎，以刺激性干咳、发热、头痛、肌痛为特点，肺部体征轻而X线改变明显。非淋球菌性尿道炎由沙眼衣原体D～K型及生殖支原体引起；猫抓病由汉赛巴通体所致；足菌肿属放线菌或真菌感染；莱姆病病原为伯氏疏螺旋体"},{"q":"由立克次体引起的疾病是","o":["非淋球菌性尿道炎","猫抓病","足菌肿","原发性非典型性肺炎","莱姆病"],"a":1,"e":"猫抓病由汉赛巴通体引起，该菌属立克次体目巴通体科，经猫抓咬伤口侵入，局部出现丘疹、脓疱并伴淋巴结肿大，可合并结膜炎与耳前淋巴结肿大的帕里诺眼淋巴结综合征。非淋球菌性尿道炎病原为沙眼衣原体；原发性非典型性肺炎由肺炎支原体引起；足菌肿为放线菌或真菌所致；莱姆病由伯氏疏螺旋体经蜱传播"},{"q":"由沙眼衣原体引起的疾病是","o":["非淋球菌性尿道炎","猫抓病","足菌肿","原发性非典型性肺炎","莱姆病"],"a":0,"e":"沙眼衣原体D～K型经性接触侵犯尿道与宫颈，引起非淋菌性尿道炎、宫颈炎，并可致附睾炎、输卵管炎与不孕。猫抓病病原是汉赛巴通体；足菌肿由放线菌或真菌引起；原发性非典型性肺炎病原为肺炎支原体；莱姆病由伯氏疏螺旋体经蜱叮咬传播"},{"q":"由放线菌引起的疾病是","o":["非淋球菌性尿道炎","猫抓病","足菌肿","原发性非典型性肺炎","莱姆病"],"a":2,"e":"足菌肿为慢性化脓性肉芽肿，其中放线菌性足菌肿由马杜拉放线菌、星形诺卡菌等经伤口植入引起，局部肿胀、形成窦道并排出含菌落的颗粒。非淋球菌性尿道炎病原为沙眼衣原体；猫抓病由汉赛巴通体所致；原发性非典型性肺炎由肺炎支原体引起；莱姆病病原为伯氏疏螺旋体"},{"q":"艾滋病","o":["急性病毒感染","持续性病毒感染","慢性病毒感染","潜伏病毒感染","慢发病毒感染"],"a":4,"e":"慢发病毒感染指显性或隐性感染后经数月至数十年潜伏期才发病，症状出现后进行性加重并致死，HIV所致艾滋病为典型代表，麻疹病毒引起的SSPE同属此类。潜伏病毒感染以单纯疱疹病毒为代表，病毒基因长期静息、可被激活复发；慢性病毒感染如慢性乙型、丙型肝炎，病毒持续存在且可检出"},{"q":"甲型肝炎","o":["急性病毒感染","持续性病毒感染","慢性病毒感染","潜伏病毒感染","慢发病毒感染"],"a":0,"e":"甲型肝炎经粪-口传播，潜伏期短，病毒在肝细胞内增殖后随胆汁排入肠道，病程自限，多数数周内痊愈，属病原消灭型急性感染，不转为慢性。慢性病毒感染如慢性乙型、丙型肝炎，病毒持续携带；潜伏病毒感染以单纯疱疹病毒为代表；慢发病毒感染见于HIV与麻疹病毒所致SSPE"},{"q":"单纯疱疹","o":["急性病毒感染","持续性病毒感染","慢性病毒感染","潜伏病毒感染","慢发病毒感染"],"a":3,"e":"HSV原发感染后残存病毒沿感觉神经轴突上行，以非复制状态潜伏于三叉神经节或骶神经节，机体免疫力下降时再激活，引起复发性口唇疱疹或生殖器疱疹。急性病毒感染如甲型肝炎，病程短、病毒被清除；慢性病毒感染如慢性乙型肝炎，病毒持续存在；慢发病毒感染以HIV、麻疹病毒所致SSPE为代表"},{"q":"慢性活动性乙型肝炎","o":["急性病毒感染","持续性病毒感染","慢性病毒感染","潜伏病毒感染","慢发病毒感染"],"a":2,"e":"慢性乙型肝炎病毒未被清除，血中持续可检出HBsAg与HBV DNA，肝功能反复异常，属慢性病毒感染，可经输血、注射传播。潜伏病毒感染以HSV潜伏于神经节为代表；慢发病毒感染如HIV与麻疹病毒所致SSPE；急性病毒感染如甲型肝炎，病程自限、病毒很快清除"},{"q":"乙型肝炎无症状携带者","o":["急性病毒感染","持续性病毒感染","慢性病毒感染","潜伏病毒感染","慢发病毒感染"],"a":1,"e":"HBV感染后病毒可在体内持续数月至数十年，无症状而长期携带，成为重要传染源，属持续性病毒感染，其下再分慢性感染、潜伏感染等类型。急性病毒感染如甲型肝炎，病原被清除、病后获稳固免疫；慢发病毒感染以HIV与麻疹病毒SSPE为代表；潜伏感染见于疱疹病毒长期静息"},{"q":"与宫颈癌有密切关系的病毒是","o":["狂犬病病毒","人乳头瘤病毒","人类细小病毒B19","人类免疫缺陷病毒","水痘-带状疱疹病毒"],"a":1,"e":"高危型HPV16、18型编码E6、E7蛋白，分别降解p53与pRb，使细胞周期失控，病毒DNA整合入宿主基因组，是宫颈癌的必要致病因素。狂犬病病毒为嗜神经病毒，引起脑脊髓炎；人类细小病毒B19引起传染性红斑与胎儿水肿；HIV破坏CD4+T细胞；水痘-带状疱疹病毒引起水痘与带状疱疹"},{"q":"嗜神经病毒是","o":["狂犬病病毒","人乳头瘤病毒","人类细小病毒B19","人类免疫缺陷病毒","水痘-带状疱疹病毒"],"a":0,"e":"狂犬病病毒属弹状病毒科，沿外周神经轴浆逆行至中枢神经系统，在海马锥体细胞胞质内形成内氏小体，表现为恐水、吞咽肌痉挛，病死率近100%。人乳头瘤病毒嗜皮肤黏膜上皮；人类细小病毒B19嗜红系祖细胞；HIV嗜CD4+T细胞与巨噬细胞；水痘-带状疱疹病毒先侵犯呼吸道黏膜再经血播散"},{"q":"嗜人类上皮细胞的病毒是","o":["狂犬病病毒","人乳头瘤病毒","人类细小病毒B19","人类免疫缺陷病毒","水痘-带状疱疹病毒"],"a":1,"e":"HPV无包膜，衣壳蛋白结合基底细胞表面受体，感染皮肤黏膜复层鳞状上皮，在分化细胞中完成复制，引起寻常疣、尖锐湿疣及宫颈上皮内瘤变。狂犬病病毒嗜神经组织；人类细小病毒B19嗜红系祖细胞；HIV侵犯CD4+T细胞与巨噬细胞；水痘-带状疱疹病毒经呼吸道黏膜入血后嗜皮肤与神经节"},{"q":"可引起猩红热的细菌","o":["A群链球菌","肺炎链球菌","甲型溶血性链球菌","脑膜炎奈瑟菌","金黄色葡萄球菌"],"a":0,"e":"A群链球菌即化脓性链球菌，产生致热外毒素（红疹毒素），引起猩红热，表现为发热、咽峡炎、全身弥漫性鲜红皮疹与草莓舌，疹退后脱屑。肺炎链球菌主要引起大叶性肺炎；甲型溶血性链球菌引起龋齿与亚急性感染性心内膜炎；脑膜炎奈瑟菌引起流脑；金黄色葡萄球菌以化脓性感染与食物中毒为主"},{"q":"可引起亚急性细菌性心内膜炎的细菌","o":["A群链球菌","肺炎链球菌","甲型溶血性链球菌","脑膜炎奈瑟菌","金黄色葡萄球菌"],"a":2,"e":"甲型溶血性链球菌即草绿色链球菌，是亚急性感染性心内膜炎最常见的病原菌，细菌多源于口腔，黏附于已有病变的瓣膜形成赘生物并反复入血。A群链球菌引起咽炎、猩红热与风湿热；肺炎链球菌引起大叶性肺炎；脑膜炎奈瑟菌引起流行性脑脊髓膜炎；金黄色葡萄球菌多致急性心内膜炎"},{"q":"可引起大叶性肺炎的细菌","o":["A群链球菌","肺炎链球菌","甲型溶血性链球菌","脑膜炎奈瑟菌","金黄色葡萄球菌"],"a":1,"e":"肺炎链球菌有荚膜，能抵抗吞噬，成人大叶性肺炎多由1、2、3型引起，儿童以14型常见，病变呈肺段实变。A群链球菌引起咽炎、猩红热与风湿热；甲型溶血性链球菌致心内膜炎；脑膜炎奈瑟菌经呼吸道入血引起流脑；金黄色葡萄球菌引起支气管肺炎与肺脓肿，常继发于流感"},{"q":"人类历史上第一个被发现的病原菌是","o":["炭疽杆菌","布鲁氏菌","钩端螺旋体","鼠疫耶尔森菌","铜绿假单胞菌"],"a":0,"e":"炭疽芽胞杆菌由郭霍于1876年分离并证实为炭疽病原，是人类历史上第一个被确认的致病菌，也是郭霍法则的经典验证对象。鼠疫耶尔森菌由耶尔森发现，引起鼠疫；布鲁氏菌引起波浪热；钩端螺旋体引起钩体病；铜绿假单胞菌为机会致病菌，多引起烧伤创面与医院内感染"},{"q":"传播媒介是鼠蚤的是","o":["炭疽杆菌","布鲁氏菌","钩端螺旋体","鼠疫耶尔森菌","铜绿假单胞菌"],"a":3,"e":"鼠疫耶尔森菌以啮齿动物为贮存宿主，鼠蚤为传播媒介，蚤吸血时细菌在其前胃形成生物膜，叮咬人时反流注入，引起腺鼠疫、肺鼠疫或败血症型鼠疫。炭疽杆菌经接触畜产品、吸入芽胞传播；布鲁氏菌经接触病畜或食入未消毒乳制品传播；钩端螺旋体经疫水接触传播；铜绿假单胞菌为机会感染"},{"q":"菌落边缘呈卷发状的是","o":["炭疽杆菌","布鲁氏菌","钩端螺旋体","鼠疫耶尔森菌","铜绿假单胞菌"],"a":0,"e":"炭疽芽胞杆菌在普通琼脂上培养24小时形成灰白色粗糙型菌落，低倍镜下边缘呈卷发状，血平板上不溶血，是该菌鉴定要点。布鲁氏菌生长缓慢、初次分离需5%～10%CO2；鼠疫耶尔森菌菌落呈碎玻璃样；钩端螺旋体需柯氏培养基、生长更慢；铜绿假单胞菌菌落有金属光泽与特殊气味"},{"q":"疱疹病毒形成的包涵体是","o":["核内嗜酸性","核内嗜碱性","胞浆嗜酸性","胞浆嗜碱性","核内及胞浆嗜酸性"],"a":0,"e":"疱疹病毒感染细胞后核内出现嗜酸性包涵体，H-E染色可见核内红色小体，取疱液、皮肤刮取物做组织学检查有助于诊断。腺病毒包涵体为核内嗜碱性；狂犬病病毒的内氏小体位于胞质且嗜酸性；麻疹病毒在核内与胞质均见嗜酸性包涵体；痘病毒包涵体位于胞质"},{"q":"巨细胞病毒形成的包涵体是","o":["核内嗜酸性","核内嗜碱性","胞浆嗜酸性","胞浆嗜碱性","核内及胞浆嗜酸性"],"a":4,"e":"巨细胞病毒感染细胞体积显著增大，核内出现巨大嗜酸性包涵体、周围有透明晕，形似猫头鹰眼，胞质内亦可见嗜酸性包涵体，是组织学诊断的重要依据。单纯疱疹病毒包涵体限于核内；腺病毒为核内嗜碱性；狂犬病病毒为胞质内嗜酸性内氏小体；痘病毒包涵体仅见于胞质"},{"q":"在宿主细胞中腺病毒形成的包涵体是","o":["核内嗜酸性","核内嗜碱性","胞浆嗜酸性","胞浆嗜碱性","核内及胞浆嗜酸性"],"a":1,"e":"腺病毒感染上皮细胞后在核内形成嗜碱性包涵体，病毒亦在核内装配，包涵体可作为细胞学诊断的参考。疱疹病毒包涵体为核内嗜酸性；狂犬病病毒内氏小体位于胞质且嗜酸性；麻疹病毒在核内与胞质均形成嗜酸性包涵体；痘病毒包涵体位于胞质"},{"q":"麻疹病毒形成的包涵体是","o":["核内嗜酸性","核内嗜碱性","胞浆嗜酸性","胞浆嗜碱性","核内及胞浆嗜酸性"],"a":4,"e":"麻疹病毒在受染细胞的核内与胞质内均形成嗜酸性包涵体，并引起细胞融合形成多核巨细胞（华新巨细胞），为麻疹的病理特征。疱疹病毒包涵体局限于核内；腺病毒为核内嗜碱性；狂犬病病毒为胞质内嗜酸性的内氏小体；痘病毒包涵体仅位于胞质"},{"q":"狂犬病毒形成的包涵体是","o":["核内嗜酸性","核内嗜碱性","胞浆嗜酸性","胞浆嗜碱性","核内及胞浆嗜酸性"],"a":2,"e":"狂犬病病毒在中枢神经细胞（海马锥体细胞）胞质内形成圆形或椭圆形嗜酸性包涵体，即内氏小体，脑组织切片或涂片找到即可辅助诊断狂犬病。疱疹病毒包涵体在核内；腺病毒为核内嗜碱性；麻疹病毒核内与胞质均有；痘病毒虽在胞质，但无内氏小体的形态与诊断意义"},{"q":"以鼠作为主要传染源的病毒是","o":["登革病毒","汉坦病毒","发热伴血小板减少综合征病毒","流行性乙型脑炎病毒","新疆出血热病毒"],"a":1,"e":"汉坦病毒属布尼亚病毒目汉坦病毒科，鼠类为贮存宿主与传染源，经吸入带毒鼠排泄物气溶胶、消化道或螨媒传播，靶细胞为血管内皮细胞，引起肾综合征出血热与汉坦病毒肺综合征。登革病毒以蚊为媒介、人为传染源；乙脑病毒以猪为扩增宿主；发热伴血小板减少综合征病毒与新疆出血热病毒均经蜱传播"},{"q":"以猪作为主要传染源的病毒是","o":["登革病毒","汉坦病毒","发热伴血小板减少综合征病毒","流行性乙型脑炎病毒","新疆出血热病毒"],"a":3,"e":"猪尤其幼猪是乙脑病毒的主要扩增宿主与传染源，病毒在猪间经蚊传播形成高病毒血症，再经三带喙库蚊叮咬传人，故流行季节与猪感染高峰一致。汉坦病毒以鼠为传染源；登革病毒在人与蚊之间循环；发热伴血小板减少综合征病毒与新疆出血热病毒均以蜱为媒介"},{"q":"以三带喙库蚊为最主要传播媒介的是","o":["登革病毒","汉坦病毒","发热伴血小板减少综合征病毒","流行性乙型脑炎病毒","新疆出血热病毒"],"a":3,"e":"三带喙库蚊是乙脑病毒的主要传播媒介，兼吸猪血与人血，病毒在其唾液腺增殖后经叮咬传播，媒介密度与季节决定流行强度。登革病毒主要由埃及伊蚊和白纹伊蚊传播；汉坦病毒经鼠类排泄物气溶胶传播，无蚊媒环节；发热伴血小板减少综合征病毒与新疆出血热病毒均经蜱传播"},{"q":"可因为疫苗接种后毒力回复而致的疾病是","o":["脊髓灰质炎","心肌炎","手足口病","无菌性脑膜炎","流行性乙型脑炎"],"a":0,"e":"口服脊髓灰质炎减毒活疫苗在肠道增殖中可发生基因突变与重组，毒力回复形成疫苗衍生脊髓灰质炎病毒，引起疫苗相关麻痹型脊髓灰质炎，多见于免疫功能低下者。手足口病由EV-A71、CVA16引起；无菌性脑膜炎多由CVB所致；心肌炎与CVB感染相关；乙脑由乙脑病毒经蚊传播"},{"q":"主要临床表现为手、足、臀等部位皮肤现斑丘疹或水疱疹的疾病是","o":["脊髓灰质炎","心肌炎","手足口病","无菌性脑膜炎","流行性乙型脑炎"],"a":2,"e":"手足口病好发于6个月至3岁儿童，由EV-A71、CVA16等引起，表现为手、足、臀部斑丘疹或疱疹及口腔黏膜疱疹，可伴发热，EV-A71所致者易并发脑干脑炎与神经源性肺水肿。脊髓灰质炎以不对称弛缓性瘫痪为特征；无菌性脑膜炎表现为脑膜刺激征；心肌炎由CVB引起；乙脑有高热与意识障碍"},{"q":"几乎所有肠道病毒都有关的疾病是","o":["脊髓灰质炎","心肌炎","手足口病","无菌性脑膜炎","流行性乙型脑炎"],"a":3,"e":"几乎各型肠道病毒均可侵犯脑膜引起无菌性脑膜炎，以CVB及CVA7、CVA9多见，夏秋季高发，表现为发热、头痛、颈项强直。脊髓灰质炎仅由脊髓灰质炎病毒1～3型引起；手足口病主要由EV-A71与CVA16所致；心肌炎以CVB为主；乙脑由虫媒的乙脑病毒引起"},{"q":"肠道病毒不会引起的疾病是","o":["脊髓灰质炎","心肌炎","手足口病","无菌性脑膜炎","流行性乙型脑炎"],"a":4,"e":"流行性乙型脑炎由乙脑病毒经蚊传播，属虫媒病毒，不属肠道病毒。肠道病毒可引起脊髓灰质炎、无菌性脑膜炎与脑炎、心肌炎及急性出血性结膜炎，柯萨奇A组致疱疹性咽峡炎，B组致心肌炎与心包炎"},{"q":"通过噬菌体将供体菌DNA片段转移到受体菌，称为","o":["转化","转导","溶原性转换","原生质体融合","接合"],"a":1,"e":"转导是以噬菌体为载体，将供体菌DNA片段导入受体菌并使其获得新性状，分普遍性转导与局限性转导，前者可转移任何DNA片段，毒性噬菌体与温和噬菌体均可介导。转化是受体菌直接摄取游离DNA；接合经性菌毛传递质粒；溶原性转换是前噬菌体基因随染色体复制使细菌获得新性状；原生质体融合为人工手段"},{"q":"受体菌直接摄取供体菌游离的DNA，称为","o":["转化","转导","溶原性转换","原生质体融合","接合"],"a":0,"e":"转化指受体菌处于感受态时直接摄取供体菌游离DNA片段，并整合于基因组获得新性状，肺炎链球菌荚膜性状的转移即经典例证。转导需噬菌体介导；接合需性菌毛接触传递质粒；溶原性转换由前噬菌体基因表达引起，如白喉毒素的产生；原生质体融合为实验室人工方法"},{"q":"细菌染色体整合有前噬菌体而获得新的遗传性状，称为","o":["转化","转导","溶原性转换","原生质体融合","接合"],"a":2,"e":"温和噬菌体感染后其基因组整合于宿主染色体成为前噬菌体，随染色体复制传给子代，使细菌获得噬菌体基因编码的性状，如白喉棒状杆菌产生白喉毒素、肉毒梭菌产毒。转导是噬菌体误包装并转移宿主DNA片段，性状来自供体菌；转化由游离DNA引起；接合经性菌毛传递质粒"},{"q":"通过性菌毛连接沟通，将DNA从供体菌转移至受体菌，称为","o":["转化","转导","溶原性转换","原生质体融合","接合"],"a":4,"e":"接合是供体菌经性菌毛与受体菌建立通道，将质粒DNA如F质粒、R质粒以单链形式转移，使受体菌获得新性状，是耐药性在革兰阴性菌间迅速扩散的主要方式。转化由受体菌摄取游离DNA；转导经噬菌体介导；溶原性转换源于前噬菌体基因；原生质体融合为人工方法"},{"q":"既有溶原性周期也有溶菌性周期的是","o":["前噬菌体","毒性噬菌体","温和噬菌体","β-棒状杆菌噬菌体","溶原性细菌"],"a":2,"e":"温和噬菌体兼具溶原性周期与溶菌性周期，感染后既可整合为前噬菌体随细菌分裂传代，也可在诱导下进入溶菌周期裂解细菌。毒性噬菌体只有溶菌性周期；前噬菌体是整合状态的核酸，本身无感染性；溶原性细菌是携带前噬菌体的宿主菌；β-棒状杆菌噬菌体只是温和噬菌体中的一种"},{"q":"只有溶菌性周期没有溶原性周期的是","o":["前噬菌体","毒性噬菌体","温和噬菌体","β-棒状杆菌噬菌体","溶原性细菌"],"a":1,"e":"毒性噬菌体感染宿主菌后只进行复制增殖，经吸附、穿入、生物合成、装配与释放而裂解细菌，没有溶原性周期。温和噬菌体两种周期兼有；前噬菌体为整合于染色体的静止状态；溶原性细菌为携带前噬菌体的菌株，不被同种噬菌体重复感染"},{"q":"整合在细菌染色体上并随细菌染色体复制而复制的是","o":["前噬菌体","毒性噬菌体","温和噬菌体","β-棒状杆菌噬菌体","溶原性细菌"],"a":0,"e":"前噬菌体是温和噬菌体基因组整合于宿主菌染色体后的存在形式，随染色体复制而复制，并随细菌分裂传给子代，不引起裂解。毒性噬菌体游离存在、复制后裂解细菌；温和噬菌体指病毒本身，可有游离颗粒状态；溶原性细菌是携带前噬菌体的细菌；β-棒状杆菌噬菌体须整合后才成为前噬菌体"},{"q":"在固体培养基上与宿主菌混合接种后可产生噬斑的是","o":["前噬菌体","毒性噬菌体","温和噬菌体","β-棒状杆菌噬菌体","溶原性细菌"],"a":1,"e":"毒性噬菌体与宿主菌在固体平板上混合接种，裂解细菌形成局限的透明空斑即噬斑，一个噬斑来自一个噬菌体，可据此计数活噬菌体（PFU/ml）。温和噬菌体需诱导才裂解宿主，平板上不形成典型噬斑；前噬菌体无感染性；溶原性细菌本身是菌，不产生噬斑"},{"q":"分离衣氏放线菌用","o":["需氧培养，普通培养基","BCYE培养基","罗氏培养基","碱性蛋白胨水","厌氧培养，初次分离加5%CO2"],"a":4,"e":"放线菌属为厌氧或微需氧菌，生长缓慢，初次分离须在厌氧环境并补充5%CO2才能良好生长，血平板上4～6天形成灰白色粗糙微小菌落，镜下呈蛛网状菌丝。结核分枝杆菌用罗氏培养基；霍乱弧菌用碱性蛋白胨水增菌；军团菌用BCYE培养基；普通培养基需氧培养不能分离本菌"},{"q":"分离结核杆菌用","o":["需氧培养，普通培养基","BCYE培养基","罗氏培养基","碱性蛋白胨水","厌氧培养，初次分离加5%CO2"],"a":2,"e":"结核分枝杆菌专性需氧、营养要求高，改良罗氏培养基含蛋黄、甘油与孔雀绿，后者抑制杂菌，接种后3～4周才见菜花状粗糙菌落，分离培养常需4～8周。霍乱弧菌用碱性蛋白胨水；军团菌用BCYE；放线菌需厌氧加5%CO2；普通培养基不能满足其营养要求"},{"q":"分离霍乱弧菌用","o":["需氧培养，普通培养基","BCYE培养基","罗氏培养基","碱性蛋白胨水","厌氧培养，初次分离加5%CO2"],"a":3,"e":"霍乱弧菌耐碱不耐酸，在pH8.8～9.0的碱性蛋白胨水中生长迅速并形成菌膜，其他细菌受抑，故用作初次分离的增菌液，6～8小时后取菌膜涂片并转种TCBS平板。结核分枝杆菌用罗氏培养基；军团菌用BCYE；放线菌需厌氧加5%CO2；普通培养基无选择性"},{"q":"无性菌毛的菌株为","o":["F+菌","F-菌","F'菌","Hfr菌","F菌"],"a":1,"e":"F-菌不含F质粒，不能编码性菌毛，故无性菌毛，接合时只能作为受体菌。F+菌含游离F质粒并表达性菌毛，为供体菌；Hfr菌的F质粒整合于染色体，同样有性菌毛；F′菌携带带染色体片段的F′质粒，也具性菌毛"},{"q":"在接合过程中作为供体菌的是","o":["F+菌","F-菌","F'菌","Hfr菌","F菌"],"a":0,"e":"F+菌含游离F质粒，编码性菌毛，接合时作为供体菌，将F质粒单链经接合桥转入F-菌，自身仍保留F质粒。F-菌无F质粒与性菌毛，是受体菌；Hfr菌与F′菌虽也能作供体，但转移的是染色体片段或F′质粒，与本题所指的质粒供体不同"},{"q":"具有性菌毛并带有宿主菌部分染色体的细菌是","o":["F+菌","F-菌","F'菌","Hfr菌","F菌"],"a":2,"e":"F′菌携带的F′质粒由F质粒错误切离形成，带有整合位点旁的宿主染色体片段，故该菌既有性菌毛又携带部分染色体基因，接合时可将这些基因高频转移给受体菌。F+菌只有游离F质粒；F-菌无性菌毛；Hfr菌的F质粒整合于染色体，转移的是整条染色体，需长时间接合"},{"q":"可将F质粒整合在宿主菌染色体上，从而导致宿主菌染色体基因高频转移的细菌是","o":["F+菌","F-菌","F'菌","Hfr菌","F菌"],"a":3,"e":"Hfr菌的F质粒整合于染色体并与染色体同步复制，接合时由转移起点牵动染色体单链进入受体菌，故染色体基因转移频率很高，但接合桥易断裂，只转入不同长度的片段。F+菌只转移F质粒本身，染色体基因转移频率极低；F′菌转移的是带小段染色体的F′质粒；F-菌为受体菌"},{"q":"与胃炎、胃溃疡及胃癌特别是胃淋巴瘤相关的是","o":["幽门螺杆菌","艰难梭菌","大肠埃希菌","白假丝酵母菌","新生隐球菌"],"a":0,"e":"幽门螺杆菌定植于胃黏膜上皮表面与黏液层下，产尿素酶分解尿素产氨以中和胃酸，其cag致病岛编码的CagA等毒力因子与慢性胃炎、消化性溃疡、胃MALT淋巴瘤及胃癌密切相关，被WHO列为Ⅰ类致癌因子。艰难梭菌引起抗生素相关性腹泻；大肠埃希菌为泌尿道感染常见菌；白念珠菌与新生隐球菌属真菌"},{"q":"泌尿道感染的常见病原体是","o":["幽门螺杆菌","艰难梭菌","大肠埃希菌","白假丝酵母菌","新生隐球菌"],"a":2,"e":"大肠埃希菌是泌尿道感染最常见的病原菌，多源于肠道经尿道上行，P菌毛黏附尿路上皮、溶血素等加重组织损伤。艰难梭菌与抗生素相关性结肠炎有关；幽门螺杆菌致胃炎与消化性溃疡；白念珠菌多在免疫力低下时引起念珠菌病；新生隐球菌主要引起中枢神经系统隐球菌脑膜炎"},{"q":"抗生素相关性结肠炎的常见病原体是","o":["幽门螺杆菌","艰难梭菌","大肠埃希菌","白假丝酵母菌","新生隐球菌"],"a":1,"e":"艰难梭菌为厌氧芽胞杆菌，滥用林可霉素、头孢菌素、喹诺酮类后肠道菌群失调，芽胞发芽繁殖并产生毒素A与毒素B，引起假膜性结肠炎与医源性腹泻，是抗生素相关性结肠炎的代表病原。大肠埃希菌为泌尿道感染常见菌；幽门螺杆菌致胃炎；白念珠菌与新生隐球菌为真菌"},{"q":"阴道炎的常见病原体是","o":["幽门螺杆菌","艰难梭菌","大肠埃希菌","白假丝酵母菌","新生隐球菌"],"a":3,"e":"白念珠菌为人体正常菌群，在妊娠、糖尿病、长期使用广谱抗生素或免疫抑制剂时大量繁殖，引起外阴阴道念珠菌病，表现为豆渣样白带与外阴瘙痒。艰难梭菌致假膜性结肠炎；幽门螺杆菌寄居于胃；大肠埃希菌虽可参与混合感染但非主要病原；新生隐球菌主要引起脑膜炎"},{"q":"外科手术敷料使用前宜采用的灭菌方法是","o":["160℃～170℃干烤2小时","紫外线照射法","焚烧法","过滤除菌法","高压蒸汽灭菌法"],"a":4,"e":"高压蒸汽灭菌法在121℃、103.4kPa下维持15～30分钟，可杀灭包括芽胞在内的一切微生物，是敷料、手术器械、注射器等耐高温耐湿物品的首选灭菌方法，以芽胞是否被杀灭判断效果。干烤适用于玻璃器皿；紫外线只用于空气与物体表面；焚烧用于废弃物品与动物尸体；过滤除菌用于不耐热液体"},{"q":"玻璃器皿、滤器、玻璃注射器等的灭菌","o":["160℃～170℃干烤2小时","紫外线照射法","焚烧法","过滤除菌法","高压蒸汽灭菌法"],"a":0,"e":"干烤灭菌一般160℃2小时或171℃1小时，适用于耐高温、不蒸发、不耐湿的物品，如玻璃器皿、试管、吸管与玻璃注射器。高压蒸汽虽效力最强但会残留水分，不利于干燥玻璃器材；紫外线穿透力弱仅用于表面；焚烧破坏物品；过滤除菌用于液体"},{"q":"空气或物体表面的消毒常采用","o":["160℃～170℃干烤2小时","紫外线照射法","焚烧法","过滤除菌法","高压蒸汽灭菌法"],"a":1,"e":"紫外线波长200～300nm，以265～266nm杀菌力最强，作用于DNA形成胸腺嘧啶二聚体，用于手术室、病房空气及物体表面的消毒，需在无人状态下照射1小时左右，穿透力弱、存在死角。干烤与高压蒸汽用于器械灭菌；焚烧用于废弃物；过滤除菌用于液体或空气的滤器过滤"},{"q":"有传染性的动物尸体的处理","o":["160℃～170℃干烤2小时","紫外线照射法","焚烧法","过滤除菌法","高压蒸汽灭菌法"],"a":2,"e":"焚烧是彻底的灭菌方法，适用于病理性废弃物、传染性动物尸体及污染的食品等，可直接点燃或在焚烧炉内进行。烧灼用于接种环与试管口；干烤用于玻璃器皿；高压蒸汽用于耐热耐湿器械；过滤除菌用于不耐热液体；紫外线仅用于表面与空气消毒"},{"q":"对含血清、糖的培养基的灭菌，应选用","o":["160℃～170℃干烤2小时","紫外线照射法","焚烧法","过滤除菌法","高压蒸汽灭菌法"],"a":3,"e":"血清、糖溶液遇高温会凝固变性或焦化，故采用孔径0.22μm左右的滤菌器以物理阻留方式除菌，但滤器不能除去病毒与支原体。高压蒸汽灭菌虽最有效，仅适用于耐热培养基；干烤使糖焦化变质；紫外线穿透力差、只用于表面；焚烧则彻底破坏标本"},{"q":"参与吸附宿主细胞的蛋白是","o":["流感病毒血凝素（HA）","流感病毒核蛋白（NP）","流感病毒神经氨酸酶（NA）","流感病毒基质蛋白（MP）","流感病毒RNA聚合酶（P"],"a":0,"e":"流感病毒血凝素（HA）能与宿主细胞表面含唾液酸的受体结合，介导病毒吸附与膜融合，是启动感染的蛋白，也是中和抗体的主要靶点。NA水解唾液酸，促进子代病毒出芽释放；NP为核衣壳主要成分，包装RNA；M蛋白维持病毒形态并参与装配；P蛋白负责RNA转录与复制"},{"q":"参与病毒释放和病毒扩散的蛋白是","o":["流感病毒血凝素（HA）","流感病毒核蛋白（NP）","流感病毒神经氨酸酶（NA）","流感病毒基质蛋白（MP）","流感病毒RNA聚合酶（P"],"a":2,"e":"神经氨酸酶（NA）水解感染细胞表面糖蛋白末端的N-乙酰神经氨酸，使子代病毒脱离细胞、避免自身聚集，从而促进释放与扩散，奥司他韦、扎那米韦即其抑制剂。HA负责吸附与穿入；NP与RNA结合构成核衣壳；M蛋白参与装配与出芽；P蛋白催化RNA合成"},{"q":"可刺激机体产生中和病毒感染性的保护性抗体的蛋白是","o":["流感病毒血凝素（HA）","流感病毒核蛋白（NP）","流感病毒神经氨酸酶（NA）","流感病毒基质蛋白（MP）","流感病毒RNA聚合酶（P"],"a":0,"e":"HA是流感病毒主要表面抗原，诱生的血凝抑制抗体能封闭HA与唾液酸受体结合，中和同亚型病毒，属保护性抗体，故疫苗以HA为主要成分。NA抗体主要抑制病毒释放、减轻病情；NP与M蛋白为内部抗原，诱生抗体无中和作用；P蛋白为内部酶类，不诱导中和抗体"},{"q":"丙型流感病毒缺乏的是","o":["流感病毒血凝素（HA）","流感病毒核蛋白（NP）","流感病毒神经氨酸酶（NA）","流感病毒基质蛋白（MP）","流感病毒RNA聚合酶（P"],"a":2,"e":"丙型流感病毒只有一种表面糖蛋白（HEF），兼具血凝素与酯酶活性，缺乏神经氨酸酶，故不分HA与NA，抗原性稳定、较少变异。甲型流感HA与NA兼备，且RNA分节段易发生重排，是引起大流行的型别；乙型流感同样具有HA与NA，但抗原变异较慢"},{"q":"性质属于免疫球蛋白的是","o":["外毒素","内毒素","抗毒素","类毒素","肠毒素"],"a":2,"e":"抗毒素是用类毒素免疫马后取其血清提取的免疫球蛋白制剂，化学本质为抗体，能中和相应外毒素，属人工被动免疫制品，维持时间仅2～3周。类毒素是外毒素经甲醛处理脱毒而成，本质为抗原；外毒素与肠毒素为细菌产生的毒性蛋白；内毒素为革兰阴性菌细胞壁脂多糖"},{"q":"能中和外毒素的是","o":["外毒素","内毒素","抗毒素","类毒素","肠毒素"],"a":2,"e":"抗毒素与游离外毒素特异性结合，阻断毒素与靶细胞受体结合或封闭其活性部位，形成的复合物易被吞噬细胞清除。类毒素是脱毒的外毒素，只用于免疫预防，不能中和已存在的毒素；外毒素与肠毒素本身即毒性蛋白；内毒素为脂多糖，不能被抗毒素中和"},{"q":"主要用于预防的是","o":["外毒素","内毒素","抗毒素","类毒素","肠毒素"],"a":3,"e":"类毒素是外毒素经0.3%～0.4%甲醛处理后失去毒性而保留免疫原性的制品，接种后诱导机体产生抗毒素，用于白喉、破伤风的预防，属人工主动免疫。抗毒素含现成抗体，多用于治疗与紧急预防；外毒素与肠毒素为毒性蛋白，不可直接接种；内毒素为脂多糖，毒性强不能作疫苗"},{"q":"可用于治疗或紧急预防的是","o":["外毒素","内毒素","抗毒素","类毒素","肠毒素"],"a":2,"e":"抗毒素注入后立即获得中和外毒素的能力，用于白喉、破伤风、肉毒中毒的治疗及密切接触者的紧急预防，属人工被动免疫，维持2～3周，异种血清须先做皮试。类毒素用于主动免疫预防、起效慢；外毒素与肠毒素具毒性；内毒素为脂多糖"},{"q":"革兰阳性菌细胞壁特殊的组分是","o":["细胞膜","磷壁酸","外膜","中介体","核糖体"],"a":1,"e":"磷壁酸是革兰阳性菌细胞壁特有的组分，占细胞壁干重的50%，分壁磷壁酸与脂磷壁酸，赋予细胞壁负电荷，与黏附、致热及抗原性有关。革兰阴性菌特有组分为外膜及其脂多糖；细胞膜与核糖体为两类细菌共有；中介体由细胞膜内褶形成，不属细胞壁成分"},{"q":"其功能类似真核细胞线粒体的细菌结构是","o":["细胞膜","磷壁酸","外膜","中介体","核糖体"],"a":3,"e":"中介体是革兰阳性菌细胞膜向胞质内折叠形成的囊状结构，含呼吸链酶类，扩大膜面积、促进电子传递与ATP生成，功能类似真核细胞的线粒体。细胞膜虽也含呼吸酶，但线粒体样功能归于中介体；磷壁酸与外膜为细胞壁成分；核糖体为蛋白质合成场所"},{"q":"革兰阴性菌细胞壁特殊的组分是","o":["细胞膜","磷壁酸","外膜","中介体","核糖体"],"a":2,"e":"外膜是革兰阴性菌细胞壁特有结构，由脂蛋白、脂质双层与脂多糖组成，可阻止溶菌酶、青霉素与碱性染料进入，其中脂多糖即内毒素。磷壁酸为革兰阳性菌特有；细胞膜与核糖体两类菌共有；中介体由细胞膜内褶形成，不是细胞壁特有组分"},{"q":"决定病毒特性的是","o":["核心","衣壳","核衣壳","包膜","刺突"],"a":0,"e":"病毒核心由核酸构成，携带全部遗传信息，决定病毒的复制、致病与抗原等特性，是病毒执行生命活性的物质基础。衣壳由蛋白亚单位组成，保护核酸并参与吸附；核衣壳为核心与衣壳的合称，属结构组合；包膜与刺突来自宿主膜或病毒糖蛋白，决定感染性与免疫原性"},{"q":"裸露病毒的结构是","o":["核心","衣壳","核衣壳","包膜","刺突"],"a":2,"e":"无包膜病毒仅由核心与衣壳构成核衣壳，核衣壳即其完整病毒体，亦称裸露病毒，对理化因素抵抗力较强，如肠道病毒、腺病毒。包膜与刺突只存在于包膜病毒，如流感病毒、疱疹病毒。核心仅为核酸，衣壳仅为蛋白外壳，单独均不构成完整病毒体"},{"q":"保护病毒核酸的结构是","o":["核心","衣壳","核衣壳","包膜","刺突"],"a":1,"e":"衣壳由壳粒按一定对称方式排列，包围并保护病毒核酸免受核酸酶破坏，同时参与吸附、具有免疫原性，是病毒鉴别与分类的重要依据。核心即核酸本身；包膜与刺突只见于包膜病毒，主要来自宿主细胞膜；核衣壳是核心与衣壳的复合结构"},{"q":"病毒的基本结构是","o":["核心","衣壳","核衣壳","包膜","刺突"],"a":2,"e":"病毒体的基本结构是核心与衣壳构成的核衣壳，包膜与刺突只是部分病毒的附加结构，故核衣壳为各类病毒共有的基本结构，无包膜病毒的病毒体即核衣壳。核心与衣壳是其组成部分而非整体；包膜与刺突仅包膜病毒才有"},{"q":"脊髓灰质炎病毒的最常见感染类型是","o":["隐性感染","急性感染","慢性感染","潜伏感染","顿挫感染"],"a":0,"e":"脊髓灰质炎病毒经粪-口传播，至少90%感染者因免疫力强或病毒毒力弱仅表现为隐性感染，少数病毒入血形成病毒血症后侵犯中枢神经系统，导致不对称弛缓性瘫痪。慢性感染与潜伏感染属持续性感染范畴；顿挫感染指病毒进入细胞后不能完成复制周期、无法产生完整子代"},{"q":"轮状病毒的常见感染类型是","o":["隐性感染","急性感染","慢性感染","潜伏感染","顿挫感染"],"a":1,"e":"轮状病毒侵犯小肠绒毛上皮，潜伏期短、起病急，表现为发热、呕吐与水样腹泻，病程3～8天自限，属典型急性感染。潜伏感染以疱疹病毒为代表；慢性感染见于HBV、HCV；顿挫感染指病毒在细胞内不能复制出完整子代的流产性感染"},{"q":"麻疹病毒的常见感染类型是","o":["隐性感染","急性感染","慢性感染","潜伏感染","顿挫感染"],"a":1,"e":"麻疹病毒经飞沫传播，潜伏期约10天，前驱期有Koplik斑，随后出现全身斑丘疹，病后获终身免疫、病毒被清除，属急性感染。极少数病愈后5～15年发生SSPE，属慢发病毒感染；潜伏感染以HSV为代表；慢性感染见于乙型、丙型肝炎"},{"q":"疱疹病毒都可以引起","o":["隐性感染","急性感染","慢性感染","潜伏感染","顿挫感染"],"a":3,"e":"HSV、水痘-带状疱疹病毒、巨细胞病毒、EB病毒及HHV-6均可在显性或隐性感染后将基因组长期存留于神经节或淋巴细胞，不复制而不被清除，免疫力下降时再激活，故潜伏感染是疱疹病毒最重要的共同特征。急性感染见于甲肝、麻疹；慢性感染见于HBV、HCV"},{"q":"革兰阳性菌细胞壁所特有的成分是","o":["磷壁酸","细菌细胞膜","脂多糖","参与肽聚糖合成的转肽酶","聚糖骨架的β-1,4糖苷键"],"a":0,"e":"磷壁酸为革兰阳性菌细胞壁特有成分，与肽聚糖共价连接，是重要表面抗原与黏附素，也可作为噬菌体吸附受体。脂多糖为革兰阴性菌外膜特有成分，即内毒素；细胞膜与聚糖骨架的β-1,4糖苷键两类菌均有；转肽酶为合成肽聚糖的酶，不是细胞壁结构成分"},{"q":"革兰阴性菌细胞壁所特有的成分是","o":["磷壁酸","细菌细胞膜","脂多糖","参与肽聚糖合成的转肽酶","聚糖骨架的β-1,4糖苷键"],"a":2,"e":"脂多糖位于革兰阴性菌外膜外层，由脂质A、核心多糖与特异多糖组成，脂质A是内毒素毒性的主要部分。磷壁酸为革兰阳性菌特有；细胞膜两类菌共有；肽聚糖骨架的β-1,4糖苷键普遍存在；转肽酶为合成肽聚糖的酶类"},{"q":"青霉素作用靶点是","o":["磷壁酸","细菌细胞膜","脂多糖","参与肽聚糖合成的转肽酶","聚糖骨架的β-1,4糖苷键"],"a":3,"e":"β-内酰胺类与青霉素结合蛋白即转肽酶共价结合，抑制其转肽、内肽与羧肽酶活性，阻碍肽聚糖交联，使细胞壁缺损、细菌在低渗环境中裂解。溶菌酶的靶点是聚糖骨架的β-1,4糖苷键；磷壁酸与脂多糖不是酶的靶点；细胞膜为多黏菌素的作用部位"},{"q":"溶菌酶作用靶点是","o":["磷壁酸","细菌细胞膜","脂多糖","参与肽聚糖合成的转肽酶","聚糖骨架的β-1,4糖苷键"],"a":4,"e":"溶菌酶水解N-乙酰葡萄糖胺与N-乙酰胞壁酸之间的β-1,4糖苷键，破坏聚糖骨架使细菌裂解，对革兰阳性菌作用明显，革兰阴性菌因外膜阻挡而不敏感。青霉素的靶点是转肽酶；磷壁酸与脂多糖均非溶菌酶底物；细胞膜为两性霉素、多黏菌素的作用位点"},{"q":"衣氏放线菌的特点是","o":["广泛存在于土壤中，以芽孢侵入伤口致病","广泛存在于土壤中，引起抵抗力低下者的外源性感染","为人体正常菌群，可以引起内源性感染","机体抵抗力降低时，通过伤口感染","通过接触引起医源性感染的主要病原体"],"a":2,"e":"衣氏放线菌寄居于口腔、上呼吸道与生殖道，属人体正常菌群，在拔牙、口腔黏膜损伤或免疫力下降时引起内源性感染，形成慢性化脓性肉芽肿、多发瘘管，脓中可见硫黄样颗粒。诺卡菌为土壤腐生菌，引起外源性感染；破伤风梭菌以芽胞经伤口侵入；炭疽经接触畜产品感染"},{"q":"诺卡菌的特点是","o":["广泛存在于土壤中，以芽孢侵入伤口致病","广泛存在于土壤中，引起抵抗力低下者的外源性感染","为人体正常菌群，可以引起内源性感染","机体抵抗力降低时，通过伤口感染","通过接触引起医源性感染的主要病原体"],"a":1,"e":"诺卡菌属为腐物寄生菌，广泛存在于土壤，经呼吸道或创口侵入，属外源性感染，多见于艾滋病、肿瘤及长期使用免疫抑制剂者，引起肺炎、肺脓肿或脑脓肿。放线菌属为人体正常菌群，引起内源性感染；破伤风梭菌以芽胞入伤口致病；两者均不以土壤腐生菌外源感染为特点"},{"q":"破伤风细菌的特点是","o":["广泛存在于土壤中，以芽孢侵入伤口致病","广泛存在于土壤中，引起抵抗力低下者的外源性感染","为人体正常菌群，可以引起内源性感染","机体抵抗力降低时，通过伤口感染","通过接触引起医源性感染的主要病原体"],"a":0,"e":"破伤风梭菌芽胞广泛存在于土壤与人和动物粪便中，经深部伤口（常混有泥土、锈钉）侵入，在厌氧环境中发芽繁殖并释放痉挛毒素，引起牙关紧闭与苦笑面容。放线菌属为内源性感染；诺卡菌为土壤腐生菌，多经呼吸道感染免疫低下者；炭疽经接触畜产品感染"},{"q":"USR试验和RPR试验可检测的螺旋体是","o":["梅毒螺旋体","钩端螺旋体","伯氏疏螺旋体","雅司螺旋体","回归热疏螺旋体"],"a":0,"e":"USR与RPR属非梅毒螺旋体抗原试验，以牛心类脂为抗原检测血清反应素，用于梅毒筛查与疗效观察，操作简便但特异性低，阳性者需用TPPA等确诊。钩端螺旋体用显微镜凝集试验；伯氏疏螺旋体用ELISA或免疫荧光；回归热疏螺旋体靠血涂片；雅司螺旋体与本试验无关"},{"q":"不能在无生命培养基中生长的螺旋体是","o":["梅毒螺旋体","钩端螺旋体","伯氏疏螺旋体","雅司螺旋体","回归热疏螺旋体"],"a":0,"e":"梅毒螺旋体至今不能在无生命人工培养基上生长，需接种家兔睾丸或细胞培养，故实验室诊断依赖暗视野镜检和血清学试验。奋森螺旋体、回归热螺旋体、伯氏疏螺旋体均可人工培养；钩端螺旋体可在柯氏培养基中生长"},{"q":"引起莱姆病的主要病原体是","o":["梅毒螺旋体","钩端螺旋体","伯氏疏螺旋体","雅司螺旋体","回归热疏螺旋体"],"a":2,"e":"莱姆病由伯氏疏螺旋体引起，硬蜱为传播媒介，鼠类为储存宿主，表现为慢性游走性红斑、关节炎和神经系统损害。钩端螺旋体引起钩体病，回归热疏螺旋体引起回归热，梅毒螺旋体引起梅毒，雅司螺旋体引起雅司"},{"q":"可用灭活疫苗和减毒活疫苗预防的是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":0,"e":"甲型肝炎已有甲醛灭活疫苗与减毒活疫苗，接种后产生抗-HAV保护性抗体，用于儿童与高危人群预防。HBV用基因工程HBsAg疫苗，无减毒活疫苗；HCV与HDV尚无成熟疫苗；HEV疫苗为重组蛋白疫苗，不属灭活与减毒活疫苗兼备者"},{"q":"可用丙种球蛋白和胎盘球蛋白紧急预防的病毒是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":0,"e":"甲型肝炎潜伏期较长，接触后早期注射人血清丙种球蛋白或胎盘球蛋白可提供被动保护、减轻发病。HBV暴露后预防用乙肝免疫球蛋白联合疫苗；HCV与HDV无被动免疫制品；HEV亦无特异性免疫球蛋白"},{"q":"常因食用水生贝类导致感染的病毒是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":0,"e":"HAV经粪-口传播，贝类可富集并浓缩污水中的病毒，生食毛蚶等水生贝类是我国甲肝暴发的重要途径，1988年上海甲肝流行即由此引起。HBV、HCV、HDV主要经血液与性传播；HEV虽也经消化道传播，但以水源与食物污染为主，贝类相关证据不如HAV典型"},{"q":"孕妇感染后病死率高的病毒是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":4,"e":"戊型肝炎经粪-口传播，孕妇感染后易发展为重型肝炎，妊娠晚期病死率可达15%～25%，与免疫病理损伤有关。HAV多呈自限性急性肝炎，极少重型；HBV、HCV、HDV主要经血液传播，孕妇感染主要关注母婴传播而非高病死率"},{"q":"复制时需要嗜肝DNA病毒辅助的是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":3,"e":"丁型肝炎病毒为缺陷病毒，基因组为单负链环状RNA，须借助HBV提供的HBsAg作为包膜才能装配成完整病毒体，故HDV感染只发生于HBV感染者，重叠或同时感染可加重病情。HAV、HEV为独立复制的小RNA病毒；HCV亦不需辅助病毒"},{"q":"脊髓灰质炎病毒感染细胞会引起","o":["杀细胞性感染","稳定状态感染","整合感染","慢发病毒感染","潜伏感染"],"a":0,"e":"脊髓灰质炎病毒感染脊髓前角运动神经元后抑制宿主细胞大分子合成，引起细胞变圆、坏死脱落，为杀细胞性感染，损伤由病毒直接作用造成，故遗留弛缓性瘫痪。潜伏感染见于疱疹病毒；整合感染见于逆转录病毒与肿瘤病毒；慢发病毒感染见于HIV与麻疹病毒SSPE"},{"q":"麻疹病毒感染引起的SSPE属于","o":["杀细胞性感染","稳定状态感染","整合感染","慢发病毒感染","潜伏感染"],"a":3,"e":"SSPE发生于麻疹病愈后5～15年，脑组织中的麻疹病毒为M基因变异的缺陷病毒，不能正常装配，呈持续缓慢进展，最终致死，属慢发病毒感染。潜伏感染以HSV为代表；整合感染指病毒核酸整合于宿主基因组；稳定状态感染以出芽释放、短时不裂解细胞为特征"},{"q":"流感病毒感染引起的细胞变化是","o":["杀细胞性感染","稳定状态感染","整合感染","慢发病毒感染","潜伏感染"],"a":1,"e":"流感病毒属包膜病毒，感染细胞后以出芽方式释放子代，短时间内不引起细胞裂解死亡，为稳定状态感染，并使细胞膜表面出现血凝素等新抗原。杀细胞性感染见于脊髓灰质炎病毒；整合感染见于肿瘤病毒与逆转录病毒；慢发病毒感染见于HIV；潜伏感染以HSV为代表"},{"q":"非特异性的抑制细胞内病毒复制的是","o":["中和抗体","NK细胞","补体","CTL","干扰素"],"a":4,"e":"干扰素与细胞表面受体结合，经JAK-STAT通路诱导2'-5'寡腺苷酸合成酶、蛋白激酶R等抗病毒蛋白，降解病毒mRNA并抑制蛋白翻译，从而非特异地抑制多种病毒复制，且不直接灭活病毒。中和抗体只作用于细胞外游离病毒；NK与CTL以杀伤靶细胞为主；补体需抗体激活才溶病毒"},{"q":"特异性杀伤病毒感染靶细胞的是","o":["中和抗体","NK细胞","补体","CTL","干扰素"],"a":3,"e":"CD8+CTL经TCR识别靶细胞MHCⅠ类分子提呈的病毒肽，释放穿孔素与颗粒酶，特异性杀伤病毒感染细胞，是终止病毒感染的主要机制。NK细胞杀伤无抗原特异性、不受MHC限制；中和抗体只中和胞外病毒；干扰素抑制复制而不杀伤细胞；补体需抗体参与才能溶解包膜病毒"},{"q":"与细胞外游离的病毒结合，阻止病毒吸附易感细胞的是","o":["中和抗体","NK细胞","补体","CTL","干扰素"],"a":0,"e":"中和抗体针对病毒表面抗原表位，与细胞外游离病毒结合，封闭其受体结合位点或改变表面构型，阻止病毒吸附与侵入易感细胞。CTL与NK细胞作用于已感染的靶细胞；干扰素抑制胞内病毒复制；补体单独不能识别病毒，仅在抗体存在时参与溶病毒"},{"q":"非特异性杀伤病毒感染靶细胞的是","o":["中和抗体","NK细胞","补体","CTL","干扰素"],"a":1,"e":"NK细胞不需抗原预先致敏，直接杀伤病毒感染的靶细胞，并释放IFN-γ、TNF-α增强早期抗病毒作用，是抗病毒感染中主要的固有免疫杀伤细胞。CTL的杀伤具抗原特异性并受MHCⅠ类限制；中和抗体只中和胞外病毒；干扰素抑制病毒复制；补体需抗体激活"},{"q":"可以在粪便中检测到的抗原是","o":["HDAg","HEAg","HBeAg","HBsAg","HBcAg"],"a":1,"e":"戊型肝炎病毒在肝细胞内增殖后经胆汁排入肠道，急性期粪便中可检出HEV抗原与病毒RNA，故粪便标本检测HEAg有诊断价值。HBsAg、HBeAg与HBcAg为HBV成分，主要取血清检测，HBcAg在血中不易检出；HDAg存在于肝细胞核内，血清中难以检出"},{"q":"血清阳性，表示HBV复制，具有高度传染性的抗原是","o":["HDAg","HEAg","HBeAg","HBsAg","HBcAg"],"a":2,"e":"HBeAg由前C基因编码，其消长与血中病毒颗粒基本一致，阳性提示HBV复制活跃、传染性强，是判断传染性的重要指标。HBsAg仅表示感染，不反映复制程度；抗-HBs为保护性抗体；HBcAg存在于病毒核心与肝细胞，血清中不易检出；HDAg属丁型肝炎病毒"},{"q":"是制备疫苗的主要成分，其相应抗体有中和作用的抗原是","o":["HDAg","HEAg","HBeAg","HBsAg","HBcAg"],"a":3,"e":"HBsAg大量存在于感染者血中，免疫原性强，可诱生保护性抗-HBs，是乙肝疫苗的主要成分。HBeAg与HBcAg免疫原性虽强，但由前C/C区编码，不作疫苗成分；HDAg为丁肝病毒抗原；抗-HBs是抗体而非抗原"},{"q":"在病毒感染造成的免疫病理损伤中，有补体参与的是","o":["Ⅰ型变态反应","Ⅱ型变态反应","Ⅲ型变态反应","Ⅳ型变态反应","Ⅰ型变态反应＋Ⅱ型变态反应"],"a":1,"e":"病毒抗原出现在感染细胞表面，与特异性抗体结合后经经典途径激活补体，由攻膜复合体导致细胞破坏，属Ⅱ型超敏反应。Ⅲ型由抗原抗体复合物沉积于血管壁、关节滑膜致病；Ⅳ型由CTL与Th1细胞介导、无补体参与；Ⅰ型由IgE与肥大细胞介导"},{"q":"CTL细胞对感染细胞的特异性杀伤造成的功能紊乱是","o":["Ⅰ型变态反应","Ⅱ型变态反应","Ⅲ型变态反应","Ⅳ型变态反应","Ⅰ型变态反应＋Ⅱ型变态反应"],"a":3,"e":"CTL特异性杀伤感染细胞、Th1细胞释放细胞因子引起以单个核细胞浸润为主的炎症，属Ⅳ型迟发型超敏反应，无抗体与补体参与。Ⅱ型由抗体结合细胞表面抗原并激活补体所致；Ⅲ型由免疫复合物沉积引起；Ⅰ型由IgE介导、肥大细胞脱颗粒"},{"q":"病毒抗原抗体复合物在血液循环中沉积造成的损伤是","o":["Ⅰ型变态反应","Ⅱ型变态反应","Ⅲ型变态反应","Ⅳ型变态反应","Ⅰ型变态反应＋Ⅱ型变态反应"],"a":2,"e":"病毒抗原与抗体形成可溶性复合物，随血流沉积于关节滑膜、肾小球基底膜或血管壁，激活补体并吸引中性粒细胞，造成局部损伤，属Ⅲ型超敏反应，慢性肝炎的关节症状与登革热的出血休克均与此有关。Ⅱ型为抗体直接作用于细胞表面抗原；Ⅳ型由T细胞介导"},{"q":"抗胞内菌感染的主要免疫因素是","o":["吞噬细胞","溶菌酶","抗体和补体","抗毒素","T细胞"],"a":4,"e":"胞内菌寄居在巨噬细胞内，抗体和补体难以接触，抗感染主要依靠T细胞，CD4+Th1细胞激活巨噬细胞增强杀菌，CD8+CTL杀伤感染细胞。抗体、补体主要针对胞外菌，NK细胞和巨噬细胞属固有免疫，单独作用有限"},{"q":"抗胞外菌感染的主要免疫因素是","o":["吞噬细胞","溶菌酶","抗体和补体","抗毒素","T细胞"],"a":2,"e":"抗胞外菌感染以体液免疫为主，抗体可中和毒素、调理吞噬，与补体联合经经典途径形成攻膜复合体溶菌，两者是主要免疫因素。吞噬细胞属固有免疫，需抗体与补体调理才高效；溶菌酶仅作用于革兰阳性菌肽聚糖；抗毒素只针对外毒素；T细胞主要抗胞内菌"},{"q":"有调理吞噬作用的免疫因素是","o":["吞噬细胞","溶菌酶","抗体和补体","抗毒素","T细胞"],"a":2,"e":"IgG的Fab段结合病原体、Fc段结合吞噬细胞FcγR，C3b与CR1结合，在病原体与吞噬细胞间形成桥接从而促进吞噬，抗体与补体联合作用更强。吞噬细胞是执行者而非调理因素；溶菌酶裂解肽聚糖；抗毒素仅中和外毒素；T细胞经细胞因子活化巨噬细胞"},{"q":"中和细菌外毒素的免疫因素是","o":["吞噬细胞","溶菌酶","抗体和补体","抗毒素","T细胞"],"a":3,"e":"抗毒素是特异性针对外毒素的抗体，可阻断毒素与靶细胞受体结合或封闭其活性部位，使毒素失去毒性，与毒素形成的复合物易被吞噬细胞清除。吞噬细胞与补体主要清除菌体；溶菌酶作用于肽聚糖；T细胞不产生抗体"},{"q":"肠道病毒的基因组为","o":["完整单股RNA","分节段单股RNA","完整双股RNA","分节段双股RNA","双股DNA"],"a":0,"e":"肠道病毒基因组为单一分子的单正链RNA，长约7.5kb，具感染性，可直接作为mRNA翻译出多聚蛋白再切割加工。流感病毒为分节段单负链RNA；轮状病毒为分节段双链RNA；冠状病毒为不分节段单正链RNA；双股DNA见于腺病毒等"},{"q":"流感病毒的基因组为","o":["完整单股RNA","分节段单股RNA","完整双股RNA","分节段双股RNA","双股DNA"],"a":1,"e":"流感病毒基因组为单负链RNA，分8个节段（丙型7个），节段重排是抗原转换、产生新亚型的机制。肠道病毒为不分节段的单正链RNA；轮状病毒为分节段双链RNA；冠状病毒为不分节段单正链RNA；腺病毒为双股DNA"},{"q":"轮状病毒的基因组为","o":["完整单股RNA","分节段单股RNA","完整双股RNA","分节段双股RNA","双股DNA"],"a":3,"e":"轮状病毒属呼肠病毒科，基因组为11个节段的双链RNA，各节段分别编码结构蛋白与非结构蛋白，节段重排可产生新毒株。流感病毒为分节段单负链RNA；肠道病毒为完整单正链RNA；冠状病毒为不分节段单正链RNA"},{"q":"微需氧，在大气环境中不能很好生长的是","o":["铜绿假单胞菌","幽门螺杆菌","肺炎克雷伯菌","变形杆菌","流感嗜血杆菌"],"a":1,"e":"幽门螺杆菌为微需氧菌，需5%～10%O2与5%～10%CO2环境才能生长，在大气氧浓度下生长不良，培养常用巧克力琼脂且生长缓慢。铜绿假单胞菌专性需氧、易培养；肺炎克雷伯菌与变形杆菌为兼性厌氧；流感嗜血杆菌需X、V因子但可在普通大气中培养"},{"q":"产生水溶性色素，使培养基呈绿色的是","o":["铜绿假单胞菌","幽门螺杆菌","肺炎克雷伯菌","变形杆菌","流感嗜血杆菌"],"a":0,"e":"铜绿假单胞菌产生水溶性的绿脓素和荧光素，可弥散入培养基使其呈绿色，感染脓汁亦呈绿色，故俗称绿脓杆菌。金黄色葡萄球菌色素为脂溶性，仅使菌落显色；肺炎克雷伯菌形成黏液型菌落；变形杆菌呈迁徙生长；流感嗜血杆菌需X、V因子"},{"q":"与金黄色葡萄球菌共同培养见卫星现象的是","o":["铜绿假单胞菌","幽门螺杆菌","肺炎克雷伯菌","变形杆菌","流感嗜血杆菌"],"a":4,"e":"流感嗜血杆菌生长需X因子（氯化血红素）与V因子（NAD），金黄色葡萄球菌可溶血释放NAD，故其菌落周围该菌生长旺盛、距离越远越差，形成卫星现象，用于鉴定。肺炎克雷伯菌形成黏液型菌落；变形杆菌呈迁徙生长；铜绿假单胞菌产绿色素；幽门螺杆菌微需氧"},{"q":"形成黏液型菌落，挑之有明显拉丝现象的是","o":["铜绿假单胞菌","幽门螺杆菌","肺炎克雷伯菌","变形杆菌","流感嗜血杆菌"],"a":2,"e":"肺炎克雷伯菌荚膜厚，菌落黏稠、有光泽，呈黏液型，接种环挑起可拉出长丝，以此与其他肠杆菌鉴别，其荚膜多糖是主要毒力因子。铜绿假单胞菌菌落扁平、有金属光泽与特殊气味；变形杆菌呈迁徙生长；流感嗜血杆菌有卫星现象；幽门螺杆菌培养要求高"},{"q":"呈明显迁徙生长现象的是","o":["铜绿假单胞菌","幽门螺杆菌","肺炎克雷伯菌","变形杆菌","流感嗜血杆菌"],"a":3,"e":"变形杆菌有周鞭毛、运动活泼，在固体培养基上呈波纹状迁徙生长，可布满整个平板形成一层薄膜，需提高琼脂浓度或加石炭酸抑制其扩散。肺炎克雷伯菌为黏液型菌落、可拉丝；铜绿假单胞菌产水溶性色素；流感嗜血杆菌有卫星现象；幽门螺杆菌微需氧生长"},{"q":"结核菌素的主要成分是","o":["蛋白质","多糖","脂质","糖蛋白","肽聚糖"],"a":0,"e":"结核菌素主要成分为结核蛋白，旧结核菌素是甘油肉汤培养物的加热滤液，其纯化物PPD用于皮肤试验，引起迟发型超敏反应。荚膜主要成分为多糖；索状因子为脂质，即海藻糖双分枝菌酸酯；肽聚糖为细胞壁骨架；糖蛋白并非其主要成分"},{"q":"溶菌酶引起结核分枝杆菌形成L型是作用于","o":["蛋白质","多糖","脂质","糖蛋白","肽聚糖"],"a":4,"e":"溶菌酶水解肽聚糖中N-乙酰葡萄糖胺与N-乙酰胞壁酸间的β-1,4糖苷键，使细胞壁缺损，细菌在低渗环境中变成L型或裂解。结核分枝杆菌细胞壁虽富含脂质与分枝菌酸，仍以肽聚糖为骨架，故可被溶菌酶作用而转变为L型；荚膜为多糖，不是酶的作用底物"},{"q":"索状因子的化学成分是","o":["蛋白质","多糖","脂质","糖蛋白","肽聚糖"],"a":2,"e":"索状因子是结核分枝杆菌细胞壁上的海藻糖双分枝菌酸酯，属糖脂，能破坏线粒体膜、抑制白细胞游走，与细菌在液体培养中呈索状生长有关。结核菌素主要成分为蛋白质；荚膜主要为多糖；肽聚糖为细胞壁骨架；糖蛋白不构成索状因子"},{"q":"引起婴幼儿支气管肺炎最常见的病毒是","o":["麻疹病毒","腮腺炎病毒","呼吸道合胞病毒","流感病毒","人偏肺病毒"],"a":2,"e":"呼吸道合胞病毒是婴幼儿下呼吸道感染的主要病原体，尤以2～6个月婴儿多见，引起细支气管炎和肺炎，表现为喘憋与三凹征，也是医院内感染的重要病原。麻疹病毒引起麻疹与巨细胞肺炎；腮腺炎病毒致腮腺肿大及睾丸炎；流感病毒多见于年长儿与成人；人偏肺病毒亦可致下呼吸道感染但非首位"},{"q":"可引发并发症脑脊髓炎的病毒是","o":["麻疹病毒","腮腺炎病毒","呼吸道合胞病毒","流感病毒","人偏肺病毒"],"a":0,"e":"麻疹最常见的严重并发症是脑炎，约0.1%病人在疹后一周发生迟发型超敏反应性脑脊髓炎，病死率约15%，存活者常留后遗症。腮腺炎病毒虽可致无菌性脑膜炎，但以腮腺肿大、睾丸炎为特征；RSV、流感病毒与人偏肺病毒主要损伤呼吸道，不引起脑脊髓炎"},{"q":"可引发迟发并发症亚急性硬化性全脑炎的病毒是","o":["麻疹病毒","腮腺炎病毒","呼吸道合胞病毒","流感病毒","人偏肺病毒"],"a":0,"e":"麻疹病愈后5～15年约有百万分之一发生亚急性硬化性全脑炎，脑组织中病毒M基因变异、M蛋白缺失，不能正常装配，呈慢发病毒感染过程，最终昏迷死亡。腮腺炎病毒可引起脑膜炎但不形成SSPE；RSV、流感病毒与人偏肺病毒均无此迟发并发症"},{"q":"可引发并发症睾丸炎或卵巢炎的病毒是","o":["麻疹病毒","腮腺炎病毒","呼吸道合胞病毒","流感病毒","人偏肺病毒"],"a":1,"e":"腮腺炎病毒除侵犯腮腺外，青春期及成人感染者易并发睾丸炎或卵巢炎，还可引起无菌性脑膜炎与胰腺炎，病后获牢固免疫。麻疹病毒以皮疹、Koplik斑及脑炎为特点；RSV损伤下呼吸道；流感病毒引起高热与全身中毒症状；人偏肺病毒致下呼吸道感染"},{"q":"主要经消化道传播的病原体是","o":["HIV","HAV","HCV","HSV","HPV"],"a":1,"e":"HAV经粪-口途径传播，病毒随粪便排出污染水源与食物，可引起暴发流行。HBV、HCV、HDV主要经血液、性接触及母婴传播；HIV经性接触、血液与垂直传播；HSV经密切接触与性传播；HPV经皮肤黏膜直接接触传播"},{"q":"最易形成慢性病毒感染的病原体是","o":["HIV","HAV","HCV","HSV","HPV"],"a":2,"e":"HCV基因组为单正链RNA，其依赖RNA的RNA聚合酶缺乏校正功能，形成准种并逃避免疫，40%～50%的急性感染者转为慢性，进而发展为肝硬化与肝癌。HBV成人感染仅5%～10%慢性化；HAV、HEV一般不转为慢性；HSV形成潜伏感染而非慢性携带"},{"q":"最易形成慢发病毒感染的病原体是","o":["HIV","HAV","HCV","HSV","HPV"],"a":0,"e":"HIV感染后经数年潜伏期才出现艾滋病症状，病毒持续复制并破坏CD4+T细胞，病情进行性加重而致死，属慢发病毒感染。HCV表现为慢性病毒感染；HSV形成潜伏感染，病毒静息于神经节；HAV为急性感染、可自愈；HPV多为局部增生性病变或整合感染"},{"q":"最易形成潜伏感染的病原体是","o":["HIV","HAV","HCV","HSV","HPV"],"a":3,"e":"HSV原发感染后残存病毒沿感觉神经上行，在三叉神经节或骶神经节以非复制状态长期潜伏，免疫力下降时再激活引起复发性疱疹，潜伏感染是疱疹病毒最重要的特征。HIV属慢发病毒感染；HCV为慢性感染；HAV为急性感染；HPV以局部感染与整合为主"},{"q":"引起成人急性胃肠炎爆发流行的主要病原体是","o":["柯萨奇病毒","诺如病毒","肠道腺病毒","轮状病毒","星状病毒"],"a":1,"e":"诺如病毒属杯状病毒科，传染性极强、感染剂量低，经污染食物、水与接触传播，是成人与学龄儿童急性胃肠炎暴发流行的主要病原，秋冬季高发，病程短、预后好。轮状病毒以婴幼儿重症腹泻为主；肠道腺病毒多见于婴儿；星状病毒与柯萨奇病毒多为散发病例"},{"q":"感染后不引起急性胃肠炎的病毒是","o":["柯萨奇病毒","诺如病毒","肠道腺病毒","轮状病毒","星状病毒"],"a":0,"e":"柯萨奇病毒在肠道增殖却很少引起肠道疾病，主要侵犯中枢神经、心肌、黏膜与皮肤，引起无菌性脑膜炎、心肌炎、疱疹性咽峡炎与手足口病。轮状病毒、诺如病毒、肠道腺病毒与星状病毒均以腹泻、呕吐为主要表现，属急性胃肠炎病毒"},{"q":"感染除引起腹泻外，还可伴有咽炎等呼吸道症状的病毒是","o":["柯萨奇病毒","诺如病毒","肠道腺病毒","轮状病毒","星状病毒"],"a":2,"e":"肠道腺病毒40、41型主要经粪-口传播，也可经呼吸道传播，除水样腹泻外常伴低热、呕吐、咳嗽等呼吸道症状，是婴儿病毒性腹泻的常见病原。轮状病毒以呕吐、腹泻与脱水为主；诺如病毒引起暴发流行性胃肠炎；星状病毒症状较轻；柯萨奇病毒少见肠道症状"},{"q":"引起婴幼儿腹泻最常见的病原体是","o":["柯萨奇病毒","诺如病毒","肠道腺病毒","轮状病毒","星状病毒"],"a":3,"e":"A种轮状病毒是世界范围内婴幼儿重症腹泻最常见的病原体，经粪-口传播，侵犯小肠绒毛上皮，引起水样便与脱水，在我国占病毒性胃肠炎病例的一半以上。诺如病毒在成人暴发中更突出；肠道腺病毒与星状病毒多致散发性婴儿腹泻；柯萨奇病毒很少引起肠道疾病"},{"q":"（ ）由人白细胞产生","o":["α-干扰素","β-干扰素","γ-干扰素","Ⅰ型干扰素","Ⅱ型干扰素"],"a":0,"e":"α-干扰素主要由单核巨噬细胞、B淋巴细胞及病毒感染的白细胞产生，属Ⅰ型干扰素，抗病毒作用强。β-干扰素由成纤维细胞产生；γ-干扰素由活化T细胞与NK细胞产生，属Ⅱ型干扰素，免疫调节作用突出。Ⅰ型与Ⅱ型是按抗原性划分的类别，并非产生细胞的归属"},{"q":"（ ）由T细胞产生","o":["α-干扰素","β-干扰素","γ-干扰素","Ⅰ型干扰素","Ⅱ型干扰素"],"a":2,"e":"γ-干扰素由活化的CD4+Th1、CD8+T细胞及NK细胞产生，属Ⅱ型干扰素，主要活化巨噬细胞、促进MHC分子表达，免疫调节作用最强。α-干扰素来自白细胞；β-干扰素来自成纤维细胞；Ⅰ型干扰素含α与β两种，与Ⅱ型是分类概念而非细胞来源"},{"q":"（ ）免疫调节作用较强","o":["α-干扰素","β-干扰素","γ-干扰素","Ⅰ型干扰素","Ⅱ型干扰素"],"a":4,"e":"Ⅱ型干扰素即IFN-γ，可激活巨噬细胞、促进MHCⅠ与Ⅱ类分子表达、活化NK细胞并增强CTL杀伤，免疫调节作用最突出。Ⅰ型干扰素即α与β，以抗病毒作用为主、免疫调节较弱；α、β、γ为按产生细胞划分的具体型别，其中γ即Ⅱ型"},{"q":"（ ）抗病毒作用较强","o":["α-干扰素","β-干扰素","γ-干扰素","Ⅰ型干扰素","Ⅱ型干扰素"],"a":3,"e":"Ⅰ型干扰素包括IFN-α与IFN-β，由病毒感染细胞产生，经JAK-STAT通路诱导抗病毒蛋白，广谱抑制病毒复制，是感染早期的主要防御因素。Ⅱ型干扰素即IFN-γ，以免疫调节与激活巨噬细胞为主，抗病毒作用弱于Ⅰ型；α、β分属Ⅰ型的两个成员"},{"q":"（ ）由人成纤维细胞产生","o":["α-干扰素","β-干扰素","γ-干扰素","Ⅰ型干扰素","Ⅱ型干扰素"],"a":1,"e":"β-干扰素主要由成纤维细胞及部分上皮细胞产生，属Ⅰ型干扰素，抗病毒作用与α-干扰素相近。α-干扰素来自白细胞；γ-干扰素来自活化T细胞与NK细胞，属Ⅱ型；Ⅰ型、Ⅱ型是干扰素的抗原性分类，不是产生细胞的归属"},{"q":"辅助诊断恙虫病的是","o":["外斐反应","肥达试验","阿斯科利试验","冷凝集试验","抗“O”试验"],"a":0,"e":"恙虫病东方体与变形杆菌OXK株有共同O抗原，用OXK抗原与病人血清做凝集试验即外斐反应，可辅助诊断恙虫病，但特异性低、敏感性差。肥达试验诊断肠热症；阿斯科利试验诊断炭疽；冷凝集试验辅助诊断肺炎支原体感染；抗“O”试验辅助诊断风湿热"},{"q":"辅助诊断伤寒的是","o":["外斐反应","肥达试验","阿斯科利试验","冷凝集试验","抗“O”试验"],"a":1,"e":"肥达试验用伤寒沙门菌O、H抗原及副伤寒甲、乙、丙H抗原与病人血清做凝集，O≥1:80、H≥1:160有诊断价值，双份血清效价4倍升高意义更大。外斐反应诊断立克次体病；阿斯科利试验诊断炭疽；冷凝集试验诊断支原体肺炎；抗“O”试验诊断风湿热"},{"q":"辅助诊断风湿病的是","o":["外斐反应","肥达试验","阿斯科利试验","冷凝集试验","抗“O”试验"],"a":4,"e":"A群链球菌感染后机体产生抗链球菌溶素O抗体，活动性风湿热病人ASO显著升高，常超过400单位，可作为新近感染与风湿活动的辅助指标。肥达试验诊断肠热症；外斐反应诊断立克次体病；阿斯科利试验诊断炭疽；冷凝集试验诊断支原体肺炎"},{"q":"辅助诊断炭疽病的是","o":["外斐反应","肥达试验","阿斯科利试验","冷凝集试验","抗“O”试验"],"a":2,"e":"阿斯科利试验为环状沉淀试验，用炭疽芽胞杆菌抗原免疫血清检测皮革、毛皮、尸体组织煮沸浸出液中的炭疽抗原，用于检疫与追溯诊断。肥达试验诊断肠热症；外斐反应诊断立克次体病；冷凝集试验诊断支原体肺炎；抗“O”试验诊断风湿热"},{"q":"辅助诊断肺炎支原体感染的是","o":["外斐反应","肥达试验","阿斯科利试验","冷凝集试验","抗“O”试验"],"a":3,"e":"肺炎支原体感染后血清中出现冷凝集素，即抗红细胞I抗原的IgM，4℃凝集、37℃可逆，效价≥1:32～1:64有辅助诊断价值，但特异性不高。肥达试验诊断肠热症；外斐反应诊断立克次体病；阿斯科利试验诊断炭疽；抗“O”试验诊断风湿热"},{"q":"靶部位是细菌核糖体30S亚基的S12蛋白","o":["利福平","磺胺药","链霉素","喹诺酮类药物","红霉素"],"a":2,"e":"链霉素属氨基糖苷类，与细菌核糖体30S亚基的S12蛋白及16S rRNA结合，抑制起始复合物形成并引起读码错误，为静止期杀菌剂。红霉素作用于50S亚基；利福平抑制依赖DNA的RNA聚合酶；磺胺药竞争二氢叶酸合成酶；喹诺酮类抑制DNA旋转酶"},{"q":"靶部位是细菌核糖体50S亚基的L4或L12蛋白","o":["利福平","磺胺药","链霉素","喹诺酮类药物","红霉素"],"a":4,"e":"红霉素属大环内酯类，与50S亚基的23S rRNA及L4、L12蛋白结合，抑制转肽与移位，阻断肽链延伸。链霉素作用于30S亚基；利福平抑制RNA聚合酶；磺胺药干扰叶酸代谢；喹诺酮类作用于DNA旋转酶；50S亚基也是氯霉素、林可霉素的作用位点"},{"q":"靶部位是细菌DNA旋转酶","o":["利福平","磺胺药","链霉素","喹诺酮类药物","红霉素"],"a":3,"e":"喹诺酮类抑制细菌DNA旋转酶即拓扑异构酶Ⅱ，阻断DNA复制而杀菌，氟喹诺酮类对革兰阴性菌作用强。利福平抑制依赖DNA的RNA聚合酶、阻断转录；链霉素作用于30S亚基；红霉素作用于50S亚基；磺胺药与对氨基苯甲酸竞争二氢叶酸合成酶"},{"q":"靶部位是细菌二氢叶酸合成酶","o":["利福平","磺胺药","链霉素","喹诺酮类药物","红霉素"],"a":1,"e":"磺胺药与对氨基苯甲酸结构相似，竞争结合二氢叶酸合成酶，使二氢叶酸合成减少、核酸合成受阻而抑菌。利福平靶位是依赖DNA的RNA聚合酶，阻断mRNA转录；喹诺酮类靶位是DNA旋转酶；链霉素作用于30S亚基，红霉素作用于50S亚基，均非叶酸合成酶"},{"q":"靶部位是细菌RNA聚合酶的G亚基","o":["利福平","磺胺药","链霉素","喹诺酮类药物","红霉素"],"a":0,"e":"利福平特异结合依赖DNA的RNA聚合酶β亚基，抑制mRNA转录，对结核分枝杆菌作用强。磺胺药竞争二氢叶酸合成酶；喹诺酮类抑制DNA旋转酶；红霉素结合50S亚基阻断蛋白合成；链霉素作用于30S亚基"},{"q":"分离汉坦病毒应采集","o":["咽漱液","脑组织","粪便","血液","脑脊液"],"a":3,"e":"汉坦病毒在发病早期形成病毒血症，血液中含毒量高，发病4至6天内采血分离阳性率最高。咽漱液用于流感等呼吸道病毒；粪便用于轮状病毒；脑组织用于狂犬病病毒；脑脊液用于中枢感染，均非汉坦病毒的常规分离标本"},{"q":"分离轮状病毒应采集","o":["咽漱液","脑组织","粪便","血液","脑脊液"],"a":2,"e":"轮状病毒腹泻时粪便中存在大量病毒颗粒，每克可达10的10次方，取粪便作直接电镜或免疫电镜最易检出。咽漱液对应流感病毒；脑组织对应狂犬病病毒；血液对应汉坦病毒；脑脊液用于中枢感染，均非轮状病毒的分离材料"},{"q":"分离狂犬病毒应采集","o":["咽漱液","脑组织","粪便","血液","脑脊液"],"a":1,"e":"狂犬病病毒沿神经组织扩散，脑组织含毒量高，可取脑组织悬液接种小鼠颅内分离病毒，脑组织切片查内氏小体亦可确诊。咽漱液用于流感，粪便用于轮状病毒，血液用于汉坦病毒，脑脊液分离阳性率不及脑组织"},{"q":"分离流感病毒应采集","o":["咽漱液","脑组织","粪便","血液","脑脊液"],"a":0,"e":"流感病毒侵犯呼吸道黏膜，急性期鼻咽分泌物含毒量高，取鼻咽拭子或咽漱液经抗生素处理，接种9至11日龄鸡胚羊膜腔分离。粪便用于轮状病毒；脑组织用于狂犬病病毒；血液用于汉坦病毒；脑脊液用于中枢感染"},{"q":"用理化方法杀死某些免疫原性强的菌株而制成的是","o":["死疫苗","活疫苗","抗毒素","类毒素","抗菌血清"],"a":0,"e":"灭活疫苗选抗原性强的菌株，人工培养后用加热或化学方法杀死，去除致病性而保留免疫原性，不能在体内增殖。活疫苗用减毒株，可在体内生长；类毒素是外毒素经甲醛脱毒；抗毒素与抗菌血清均为含抗体的被动免疫制品"},{"q":"所用菌株注射人体后仍可在宿主体内有一定生长繁殖的是","o":["死疫苗","活疫苗","抗毒素","类毒素","抗菌血清"],"a":1,"e":"活疫苗由减毒或无毒的活病原体制成，接种后可在体内有一定生长繁殖，类似轻型感染或隐性感染。死疫苗的菌体已被杀死，体内不增殖；类毒素为脱毒外毒素；抗毒素和抗菌血清含现成抗体，均无增殖能力"},{"q":"所用菌株注射人体后可引发较持久免疫力的是","o":["死疫苗","活疫苗","抗毒素","类毒素","抗菌血清"],"a":1,"e":"活疫苗在体内增殖并持续刺激免疫系统，兼具体液免疫和细胞免疫，维持时间可达1至5年或更长。死疫苗仅诱导体液免疫，维持约半年至1年；类毒素免疫原性弱于活疫苗；抗毒素、抗菌血清属被动免疫，仅维持2至3周"},{"q":"用细菌外毒素经甲醛液作用后制成的是","o":["死疫苗","活疫苗","抗毒素","类毒素","抗菌血清"],"a":3,"e":"外毒素经0.3%至0.4%甲醛处理，失去毒性而保留抗原性，制成类毒素，用于破伤风、白喉的主动免疫。死疫苗杀死的对象是菌体而非毒素；抗毒素是用类毒素免疫马后提取的抗体；抗菌血清含抗菌抗体，均属被动免疫"},{"q":"用减毒或无毒力的活病原体制成的是","o":["死疫苗","活疫苗","抗毒素","类毒素","抗菌血清"],"a":1,"e":"活疫苗用保留免疫原性的减毒株或无毒株制成，如卡介苗、炭疽减毒活疫苗，接种后类似轻型感染。死疫苗须用理化方法杀死菌体，体内不增殖；类毒素由外毒素脱毒而来；抗毒素、抗菌血清含现成抗体，属人工被动免疫制品"},{"q":"我国目前采用的狂犬病疫苗是","o":["灭活疫苗","减毒活疫苗","重组疫苗","核酸疫苗","多价疫苗"],"a":0,"e":"狂犬病病毒经理化方法灭活后制成灭活疫苗，失去感染性而保留抗原性，我国现用细胞培养灭活疫苗。减毒活疫苗用于麻疹、脊髓灰质炎；重组疫苗用于乙肝；核酸疫苗尚处研究阶段；多价疫苗指同一病原的多个血清型抗原"},{"q":"我国目前采用的乙肝疫苗是","o":["灭活疫苗","减毒活疫苗","重组疫苗","核酸疫苗","多价疫苗"],"a":2,"e":"我国乙肝疫苗为基因工程重组疫苗，由酵母菌或哺乳动物细胞表达HBsAg后纯化制成，按0、1、6个月接种三剂。血源灭活疫苗已被取代；乙肝无减毒活疫苗；核酸疫苗未用于常规免疫；多价疫苗指覆盖多个血清型"},{"q":"目前较多使用的流感疫苗是","o":["灭活疫苗","减毒活疫苗","重组疫苗","核酸疫苗","多价疫苗"],"a":4,"e":"流感病毒HA、NA抗原易变异，疫苗须覆盖当年流行的多个亚型，故属多价疫苗，其制备多采用灭活或裂解工艺。灭活疫苗的典型代表是狂犬病疫苗、甲肝疫苗；减毒活疫苗用于麻疹、腮腺炎；重组疫苗用于乙肝"},{"q":"我国目前采用的麻疹疫苗是","o":["灭活疫苗","减毒活疫苗","重组疫苗","核酸疫苗","多价疫苗"],"a":1,"e":"麻疹疫苗用毒力变异获得的减毒株制成，接种一次即可诱导持久免疫。灭活疫苗用于狂犬病、甲肝；重组疫苗用于乙肝；核酸疫苗尚在研发；多价疫苗指同一病原的多个血清型，麻疹病毒只有一个血清型"},{"q":"病毒感染激活细胞的死亡基因而导致","o":["杀细胞性感染","稳定状态感染","细胞增生与细胞转化","整合感染","细胞凋亡"],"a":4,"e":"病毒激活宿主细胞死亡基因，启动程序性死亡，形成凋亡小体，一般不引起炎症。杀细胞性感染是病毒阻断细胞大分子合成致细胞溶解；稳定状态感染以出芽释放、细胞不立即死亡为特征；整合感染指病毒基因插入染色体"},{"q":"病毒DNA与细胞的染色体DNA随机进行重组可导致","o":["杀细胞性感染","稳定状态感染","细胞增生与细胞转化","整合感染","细胞凋亡"],"a":3,"e":"病毒DNA全部或部分随机整合于细胞染色体DNA，称整合感染，逆转录病毒经cDNA整合，HBV可部分片段整合。杀细胞性感染导致细胞裂解；稳定状态感染细胞缓慢释放子代；细胞转化是整合后的结果而非整合过程本身"},{"q":"表现为细胞繁殖加快，失去细胞间的接触抑制，细胞形态发生变化的是","o":["杀细胞性感染","稳定状态感染","细胞增生与细胞转化","整合感染","细胞凋亡"],"a":2,"e":"病毒基因整合或病毒蛋白作用使细胞增殖加快、失去接触抑制、形态改变，即细胞转化，与肿瘤形成相关。杀细胞性感染表现为细胞溶解死亡；稳定状态感染细胞形态改变轻微、以出芽释放病毒；整合感染强调基因插入过程"},{"q":"疱疹病毒常引起","o":["杀细胞性感染","稳定状态感染","细胞增生与细胞转化","整合感染","细胞凋亡"],"a":1,"e":"疱疹病毒属包膜病毒，感染后能复制并以出芽方式缓慢释放子代，短时间内不裂解细胞，呈稳定状态感染，可形成多核巨细胞。杀细胞性感染见于脊髓灰质炎病毒、腺病毒；整合感染以基因整合为特征；细胞凋亡由死亡基因激活"},{"q":"脊髓灰质炎病毒常引起","o":["杀细胞性感染","稳定状态感染","细胞增生与细胞转化","整合感染","细胞凋亡"],"a":0,"e":"脊髓灰质炎病毒为裸露病毒，复制中阻断宿主细胞大分子合成，成熟后溶解细胞释放，属杀细胞性感染。稳定状态感染见于疱疹病毒等包膜病毒；整合感染见于逆转录病毒和HBV；细胞转化表现为增殖加快、失去接触抑制"},{"q":"（ ）即非接合性质粒","o":["插入序列","R质粒","耐药性传递因子","转座子","耐药性决定子"],"a":4,"e":"非接合性耐药质粒又称r质粒，其耐药性决定子r-det携带耐药基因但不编码性菌毛，不能自行接合传递。耐药性传递因子RTF编码性菌毛、决定接合转移；R质粒是接合性耐药质粒的整体；插入序列只编码转座酶"},{"q":"（ ）与耐药性基因或非接合性耐药质粒结合形成多重耐药的接合性质粒","o":["插入序列","R质粒","耐药性传递因子","转座子","耐药性决定子"],"a":2,"e":"耐药性传递因子RTF与F质粒功能相似，编码性菌毛，决定质粒复制、接合与转移，与耐药基因或r-det结合即形成多重耐药的接合性质粒。耐药性决定子只决定耐药性而无传递功能；插入序列仅编码转座酶；转座子介导耐药基因跳跃"},{"q":"（ ）插入基因中，使细菌产生耐药性","o":["插入序列","R质粒","耐药性传递因子","转座子","耐药性决定子"],"a":3,"e":"转座子携带耐药基因，可跳跃插入靶基因，导致插入突变、基因重排或邻近基因表达改变，使细菌获得耐药性。插入序列只编码转座酶、不携带耐药基因；R质粒是接合性耐药质粒；耐药性决定子是r-det上的耐药基因部分"},{"q":"（ ）只编码转座酶","o":["插入序列","R质粒","耐药性传递因子","转座子","耐药性决定子"],"a":0,"e":"插入序列是最简单的转座元件，长度不超过2kbp，只编码转座酶，不携带与转座无关的基因，可独立存在或作为转座子的一部分。转座子除转座基因外还携带耐药、毒力等基因；R质粒是独立复制质粒；耐药性决定子决定耐药表型"},{"q":"（ ）以接合和转化方式转移","o":["插入序列","R质粒","耐药性传递因子","转座子","耐药性决定子"],"a":1,"e":"R质粒为接合性耐药质粒，经性菌毛接合在种内或种间传递，也可经转化进入感受态菌，故耐药性迅速扩散。插入序列仅能转座；耐药性传递因子只是R质粒的接合功能部分；转座子经转座而非接合转移；耐药性决定子无传递功能"},{"q":"针对青霉素，细菌可产生","o":["氨基糖苷类钝化酶","氯霉素乙酰转移酶","甲基化酶","β-内酰胺酶","磷酸转移酶"],"a":3,"e":"β-内酰胺酶特异裂解青霉素的β-内酰胺环，使其失去抗菌活性，由染色体或质粒编码，是革兰氏阴性菌耐药的重要机制。氨基糖苷类钝化酶修饰卡那霉素、链霉素；氯霉素乙酰转移酶乙酰化氯霉素；甲基化酶修饰23S rRNA，介导大环内酯类耐药"},{"q":"针对卡那霉素，细菌可产生","o":["氨基糖苷类钝化酶","氯霉素乙酰转移酶","甲基化酶","β-内酰胺酶","磷酸转移酶"],"a":0,"e":"卡那霉素属氨基糖苷类，细菌产生氨基糖苷类钝化酶，经羟基磷酸化、氨基乙酰化或羧基腺苷酰化修饰药物，使其不能与30S亚基结合。β-内酰胺酶水解青霉素；氯霉素乙酰转移酶针对氯霉素；甲基化酶介导红霉素耐药"},{"q":"针对链霉素，细菌可产生","o":["氨基糖苷类钝化酶","氯霉素乙酰转移酶","甲基化酶","β-内酰胺酶","磷酸转移酶"],"a":0,"e":"链霉素属氨基糖苷类抗生素，耐药菌产生质粒介导的氨基糖苷类钝化酶，修饰药物使其失去结合30S亚基的能力。β-内酰胺酶作用于青霉素和头孢菌素；氯霉素乙酰转移酶灭活氯霉素；甲基化酶使23S rRNA甲基化而致大环内酯类耐药"},{"q":"针对红霉素，细菌可产生","o":["氨基糖苷类钝化酶","氯霉素乙酰转移酶","甲基化酶","β-内酰胺酶","磷酸转移酶"],"a":2,"e":"红霉素属大环内酯类，耐药菌产生甲基化酶，使23S rRNA甲基化，药物不能与50S亚基结合。β-内酰胺酶水解青霉素；氨基糖苷类钝化酶修饰卡那霉素、链霉素；氯霉素乙酰转移酶针对氯霉素，均作用于药物本身而非靶位"},{"q":"构成HIV内膜（基质蛋白）的蛋白是","o":["gp41","p24","gp120","p17","p7"],"a":3,"e":"HIV的gag基因编码p55前体，切割后形成基质蛋白p17、衣壳蛋白p24和核壳蛋白p7，p17位于核衣壳与包膜之间构成内膜。gp120是表面糖蛋白，gp41为跨膜糖蛋白，二者共同构成包膜刺突"},{"q":"可介导病毒包膜与宿主细胞融合的是","o":["gp41","p24","gp120","p17","p7"],"a":0,"e":"gp41为跨膜糖蛋白，gp120与CD4及辅助受体结合后与之分离，gp41构象改变而暴露融合肽，介导病毒包膜与细胞膜融合。gp120负责吸附受体；p24是衣壳蛋白；p17为基质蛋白；p7是核壳蛋白，均无融合功能"},{"q":"可与宿主CD4分子结合的是","o":["gp41","p24","gp120","p17","p7"],"a":2,"e":"gp120的恒定区与CD4分子结合，可变区V3与CXCR4或CCR5辅助受体结合，决定病毒亲嗜性。gp41介导膜融合；p24为衣壳蛋白；p17为基质蛋白；p7为核壳蛋白，均不结合CD4"},{"q":"HIV中特异性最高的蛋白是","o":["gp41","p24","gp120","p17","p7"],"a":1,"e":"p24是HIV衣壳蛋白，不同株间序列保守，特异性最高，ELISA检测p24抗原可用于感染早期诊断。gp120变异大、具型特异性；gp41较保守但不及p24；p17、p7为基质蛋白和核壳蛋白，抗原特异性较低"},{"q":"HIV最易变异的蛋白是","o":["gp41","p24","gp120","p17","p7"],"a":2,"e":"gp120含五个可变区，V3区为主要中和域且易发生变异，病毒借此逃避中和抗体，故最易变异。gp41变异较少；p24为衣壳蛋白、序列保守，是特异性最高的抗原；p17、p7结构稳定，变异程度低"},{"q":"与传染性单核细胞增多症有关的病原体是","o":["HHV-1","HHV-2","HHV-3","HHV-4","HHV-5"],"a":3,"e":"EB病毒即人疱疹病毒4型，经唾液传播，感染B淋巴细胞，引起传染性单核细胞增多症，并与Burkitt淋巴瘤、鼻咽癌相关。HHV-1引起唇疱疹、角膜炎；HHV-2引起生殖器疱疹；HHV-3引起水痘和带状疱疹；HHV-5引起巨细胞包涵体病"},{"q":"与水痘-带状疱疹有关的病原体是","o":["HHV-1","HHV-2","HHV-3","HHV-4","HHV-5"],"a":2,"e":"水痘-带状疱疹病毒即HHV-3，儿童期原发感染引起水痘，病毒潜伏于脊髓后根神经节，再激活引起带状疱疹。HHV-1潜伏三叉神经节引起唇疱疹；HHV-2潜伏骶神经节；HHV-4为EB病毒；HHV-5为巨细胞病毒"},{"q":"与宫颈癌有关的病原体是","o":["HHV-1","HHV-2","HHV-3","HHV-4","HHV-5"],"a":1,"e":"HSV-2即HHV-2，主要经性接触传播，与宫颈癌发生相关，其DNA可整合并转化上皮细胞。HHV-1引起唇疱疹和角膜炎；HHV-3引起水痘；HHV-4与鼻咽癌、Burkitt淋巴瘤相关；HHV-5引起巨细胞包涵体病"},{"q":"与输血后单核细胞增多症有关的病原体是","o":["HHV-1","HHV-2","HHV-3","HHV-4","HHV-5"],"a":4,"e":"HCMV即HHV-5，可潜伏于白细胞，经输血传播，引起输血后单核细胞增多症，嗜异凝集试验阴性。HHV-4的EBV引起典型传染性单核细胞增多症；HHV-1、HHV-2引起疱疹；HHV-3引起水痘和带状疱疹"},{"q":"中毒性休克综合征相关的致病物质是","o":["TSST-1","肠毒素","内毒素","凝固酶","表皮剥脱毒素"],"a":0,"e":"TSST-1是金黄色葡萄球菌分泌的超抗原，经期使用不洁卫生棉时入血，引起发热、脱屑性皮疹、多器官功能紊乱和休克。肠毒素引起食物中毒，以呕吐为主；内毒素致发热和休克但不引起脱屑；表皮剥脱毒素引起烫伤样皮肤综合征"},{"q":"病灶局限相关的致病物质是","o":["TSST-1","肠毒素","内毒素","凝固酶","表皮剥脱毒素"],"a":3,"e":"凝固酶使血浆纤维蛋白沉积于菌体表面，阻碍吞噬细胞吞噬和血清杀菌物质，并使感染局限化、形成血栓。TSST-1引起毒性休克综合征；肠毒素引起食物中毒；表皮剥脱毒素致表皮与真皮分离；内毒素引起全身反应而非局限化脓"},{"q":"食物中毒相关的致病物质是","o":["TSST-1","肠毒素","内毒素","凝固酶","表皮剥脱毒素"],"a":1,"e":"金黄色葡萄球菌肠毒素耐热，与肠道神经细胞受体结合刺激呕吐中枢，引起以呕吐为主的急性胃肠炎，即食物中毒。TSST-1引起毒性休克综合征；表皮剥脱毒素引起烫伤样皮肤综合征；凝固酶与病灶局限化有关；内毒素致发热、休克"},{"q":"烫伤样皮肤综合征相关的致病物质是","o":["TSST-1","肠毒素","内毒素","凝固酶","表皮剥脱毒素"],"a":4,"e":"表皮剥脱毒素又称表皮溶解毒素，作用于表皮颗粒层，使表皮与真皮分离，引起烫伤样皮肤综合征，多见于婴幼儿。TSST-1引起毒性休克；肠毒素引起食物中毒；凝固酶使感染局限；内毒素引起发热和微循环障碍"},{"q":"疱疹病毒的培养，一般接种于鸡胚的","o":["绒毛尿囊膜","尿囊腔","羊膜腔","卵黄囊","鸡胚"],"a":0,"e":"疱疹病毒接种于9至14日龄鸡胚的绒毛尿囊膜，可在膜上形成痘斑样病灶，天花病毒、痘苗病毒亦用此途径。尿囊腔用于流感病毒传代和腮腺炎病毒；羊膜腔用于流感病毒初次分离；卵黄囊用于嗜神经病毒和衣原体"},{"q":"流感病毒的传代培养，一般接种于鸡胚的","o":["绒毛尿囊膜","尿囊腔","羊膜腔","卵黄囊","鸡胚"],"a":1,"e":"流感病毒传代培养采用尿囊腔接种，病毒在尿囊液中增殖，不引起明显病变，需用血凝试验判定效价。绒毛尿囊膜用于疱疹病毒；羊膜腔用于初次分离；卵黄囊用于嗜神经病毒；鸡胚是整体培养载体而非接种部位"},{"q":"流感病毒的初次分离培养，一般接种于鸡胚的","o":["绒毛尿囊膜","尿囊腔","羊膜腔","卵黄囊","鸡胚"],"a":2,"e":"流感病毒初次分离以羊膜腔接种为宜，病毒在羊水中增殖，取羊水作血凝试验检测。传代培养改用尿囊腔，尿囊液中病毒滴度更高；绒毛尿囊膜用于疱疹病毒；卵黄囊用于嗜神经病毒；鸡胚并非具体接种部位"},{"q":"嗜神经病毒的培养，一般接种于鸡胚的","o":["绒毛尿囊膜","尿囊腔","羊膜腔","卵黄囊","鸡胚"],"a":3,"e":"嗜神经病毒如狂犬病病毒接种于鸡胚卵黄囊，卵黄囊营养丰富，适于神经组织嗜性病毒增殖，病毒在卵黄囊膜中大量复制。绒毛尿囊膜用于疱疹病毒和痘类病毒；尿囊腔用于流感病毒传代；羊膜腔用于流感病毒初次分离"},{"q":"引起临床黄疸出血型的病原体是","o":["回归热螺旋体","奋森螺旋体","钩端螺旋体","梅毒螺旋体","伯氏疏螺旋体"],"a":2,"e":"黄疸出血群钩端螺旋体是我国南方主要流行菌群，引起黄疸出血型钩端螺旋体病，表现为发热、黄疸、出血及肝肾损害。回归热螺旋体经虱或蜱传播引起回归热；伯氏疏螺旋体引起莱姆病；梅毒螺旋体引起梅毒；奋森螺旋体引起口腔机会感染"},{"q":"引起慢性游走性红斑的病原体是","o":["回归热螺旋体","奋森螺旋体","钩端螺旋体","梅毒螺旋体","伯氏疏螺旋体"],"a":4,"e":"伯氏疏螺旋体经硬蜱叮咬传播，引起莱姆病，早期特征为慢性游走性红斑，后期可累及神经、心脏和关节。钩端螺旋体引起黄疸出血型钩体病；回归热螺旋体引起回归热；梅毒螺旋体引起硬下疳；奋森螺旋体引起咽峡炎"},{"q":"人虱为传播媒介的病原体是","o":["回归热螺旋体","奋森螺旋体","钩端螺旋体","梅毒螺旋体","伯氏疏螺旋体"],"a":0,"e":"回归热螺旋体以人虱或软蜱为传播媒介，虱叮咬后病原体经伤口进入体内，引起周期性高热。钩端螺旋体经疫水接触传播；伯氏疏螺旋体经硬蜱传播；梅毒螺旋体经性接触传播；奋森螺旋体为口腔正常菌群"},{"q":"携带有某种病原菌但未出现临床症状的健康人为","o":["带菌者","病毒携带者","带菌动物","患者","病毒感染者"],"a":0,"e":"带菌者感染后无临床症状或症状轻微，但持续排出病原体，是重要传染源，脑膜炎奈瑟菌流行期带菌率可达70%。病毒携带者携带的是病毒；带菌动物为动物宿主，引起人兽共患病；患者有临床症状和体征"},{"q":"携带有某种病毒但未出现临床症状的健康人为","o":["带菌者","病毒携带者","带菌动物","患者","病毒感染者"],"a":1,"e":"病毒携带者感染后不出现明显症状，病毒在体内持续增殖并长期向外界排毒，是重要传染源。带菌者携带的是细菌；带菌动物指动物宿主；患者为显性感染，有临床症状和体征；病毒感染者可为隐性或显性感染"},{"q":"人畜共患病的病原体一般来自","o":["带菌者","病毒携带者","带菌动物","患者","病毒感染者"],"a":2,"e":"人兽共患病的病原体来自病畜或带菌动物，经特定途径传给人，如鼠疫、炭疽、钩端螺旋体病。带菌者和病毒携带者是人群传染源；患者是临床感染个体；病毒感染者可为隐性或显性感染，均非动物来源"},{"q":"能引起原发性非典型性肺炎","o":["唾液支原体","解脲脲原体","穿透支原体","发酵支原体","肺炎支原体"],"a":4,"e":"肺炎支原体黏附于呼吸道上皮，引起间质性肺炎，即原发性非典型性肺炎，症状较轻、以干咳为主。解脲脲原体引起非淋菌性尿道炎；穿透支原体协同HIV致病；发酵支原体引起流感样疾病和肺炎；唾液支原体多不致病"},{"q":"与艾滋病发病相关的是","o":["唾液支原体","解脲脲原体","穿透支原体","发酵支原体","肺炎支原体"],"a":2,"e":"穿透支原体可黏附并穿透宿主细胞，协同HIV感染，加速艾滋病病程进展。解脲脲原体引起非淋菌性尿道炎；肺炎支原体引起原发性非典型性肺炎；发酵支原体引起流感样疾病和关节炎；唾液支原体致病性未明"},{"q":"最常见于引起非淋菌性尿道炎","o":["唾液支原体","解脲脲原体","穿透支原体","发酵支原体","肺炎支原体"],"a":1,"e":"解脲脲原体分解尿素产氨，是泌尿生殖道常见机会致病菌，引起非淋菌性尿道炎、宫颈炎，性活跃者感染率高。肺炎支原体经呼吸道传播引起肺炎；穿透支原体协同HIV致病；发酵支原体引起关节炎和肺炎"},{"q":"森林脑炎病毒的传播媒介和储存宿主是","o":["蚊","蚤","幼猪","蜱","恙螨"],"a":3,"e":"森林脑炎病毒又称蜱传脑炎病毒，蜱既是传播媒介又是储存宿主，蝙蝠和啮齿类动物亦为储存宿主。乙脑病毒以蚊为媒介；蚤传播鼠疫；幼猪是乙脑的扩增宿主；恙螨传播恙虫病东方体，均非本病毒的媒介"},{"q":"乙型脑炎病毒的传播媒介及长期储存宿主是","o":["蚊","蚤","幼猪","蜱","恙螨"],"a":0,"e":"乙脑病毒以三带喙库蚊为主要传播媒介，蚊可带毒越冬并经卵传代，故同时是长期储存宿主；猪感染后病毒血症明显，起扩增宿主作用。蜱为森林脑炎病毒的媒介；蚤传播鼠疫；恙螨传播恙虫病东方体"},{"q":"登革热病毒的主要传播媒介是","o":["蚊","蚤","幼猪","蜱","恙螨"],"a":0,"e":"登革病毒以埃及伊蚊和白纹伊蚊为主要传播媒介，人和灵长类动物为自然宿主，病毒在蚊体内增殖并可经卵传代，形成蚊-人-蚊循环。蜱传播森林脑炎；蚤传播鼠疫；幼猪是乙脑的扩增宿主；恙螨传播恙虫病"},{"q":"CMV潜伏的部位是","o":["三叉神经节和颈上神经节","骶神经节","腺组织、肾脏、白细胞","淋巴样组织，唾液腺","淋巴样组织，B淋巴细胞"],"a":2,"e":"HCMV即HHV-5，潜伏于髓系前体细胞、分泌性腺体和肾脏、白细胞，活化后经血行播散。HSV-1潜伏三叉神经节；HSV-2潜伏骶神经节；VZV潜伏脊髓后根神经节；EBV潜伏于B淋巴细胞"},{"q":"EBV潜伏的部位是","o":["三叉神经节和颈上神经节","骶神经节","腺组织、肾脏、白细胞","淋巴样组织，唾液腺","淋巴样组织，B淋巴细胞"],"a":4,"e":"EBV以B淋巴细胞为靶细胞，感染后少量病毒持续潜伏于B淋巴细胞，可终生携带。HSV-1潜伏三叉神经节；HSV-2潜伏骶神经节；VZV潜伏脊髓后根神经节；HCMV潜伏于腺组织、肾脏和白细胞"},{"q":"HSV-1潜伏的部位是","o":["三叉神经节和颈上神经节","骶神经节","腺组织、肾脏、白细胞","淋巴样组织，唾液腺","淋巴样组织，B淋巴细胞"],"a":0,"e":"HSV-1原发感染后沿感觉神经轴突上行，潜伏于三叉神经节和颈上神经节，再激活引起唇疱疹。HSV-2潜伏骶神经节；VZV潜伏脊髓后根神经节；HCMV潜伏腺组织、肾脏和白细胞；EBV潜伏B淋巴细胞"},{"q":"BCG是一种","o":["死疫苗","活疫苗","抗毒素","类毒素","丙种球蛋白"],"a":1,"e":"卡介苗是牛型结核分枝杆菌减毒株制成的活疫苗，接种后可在体内有限增殖，诱导细胞免疫，对儿童重症结核有保护力。死疫苗如伤寒、百日咳疫苗；类毒素为外毒素脱毒制品；抗毒素为抗体；丙种球蛋白为被动免疫制剂"},{"q":"TAT是一种","o":["死疫苗","活疫苗","抗毒素","类毒素","丙种球蛋白"],"a":2,"e":"TAT即破伤风抗毒素，用破伤风类毒素免疫马后提取免疫球蛋白精制而成，用于中和游离外毒素。类毒素用于主动免疫；死疫苗、活疫苗针对菌体；丙种球蛋白为非特异性抗体，无针对破伤风毒素的特异性"},{"q":"可用于外毒素所致疾病的紧急预防和治疗","o":["死疫苗","活疫苗","抗毒素","类毒素","丙种球蛋白"],"a":2,"e":"抗毒素含特异性抗体，能立即中和体内游离外毒素，用于白喉、破伤风、肉毒中毒的治疗和紧急预防，使用前须做皮试。类毒素用于预防、产生抗体慢；死疫苗和活疫苗诱导主动免疫；丙种球蛋白为非特异性被动免疫"},{"q":"属于细菌遗传物质的是","o":["脂多糖","质粒","细胞壁","荚膜","鞭毛"],"a":1,"e":"质粒是细菌染色体外具有独立复制能力的环状双链DNA，携带耐药、毒力等基因，可通过接合、转化、转导转移。脂多糖是内毒素成分；细胞壁维持形态；荚膜抗吞噬；鞭毛是运动器官，均非遗传物质"},{"q":"维持细菌固有形态的是","o":["脂多糖","质粒","细胞壁","荚膜","鞭毛"],"a":2,"e":"细胞壁坚韧富弹性，维持菌体固有形态并抵抗胞内5至20个大气压的渗透压，其肽聚糖合成受青霉素抑制。荚膜位于壁外，抗吞噬；鞭毛与运动有关；菌毛与黏附有关；脂多糖是外膜成分，均不维持形态"},{"q":"细菌内毒素的化学成分是","o":["脂多糖","质粒","细胞壁","荚膜","鞭毛"],"a":0,"e":"内毒素化学本质为脂多糖，由脂质A、核心多糖和特异多糖组成，脂质A是毒性中心，耐热，需160℃2至4小时才被破坏。质粒是遗传物质；细胞壁是结构；荚膜为多糖或多肽；鞭毛为蛋白质，均不具备内毒素活性"},{"q":"隐性感染或患传染病或获得免疫力称为","o":["人工主动免疫","人工被动免疫","自然主动免疫","自然被动免疫","被动-主动免疫"],"a":2,"e":"隐性感染或病后获得的免疫力由机体自身产生，属自然主动免疫。人工主动免疫来自接种疫苗；人工被动免疫来自注射抗毒素或丙种球蛋白；自然被动免疫来自胎盘或初乳抗体；被动-主动免疫为先用抗体再接种疫苗"},{"q":"接种疫苗和类毒素后获得免疫力称为","o":["人工主动免疫","人工被动免疫","自然主动免疫","自然被动免疫","被动-主动免疫"],"a":0,"e":"接种疫苗和类毒素使机体自身产生抗体及致敏淋巴细胞，属人工主动免疫，出现慢但维持久。人工被动免疫注射现成抗体，出现快而维持短；自然主动免疫来自隐性感染或患病；自然被动免疫来自母体抗体"},{"q":"胎儿通过胎盘接受来自母体的抗体称为","o":["人工主动免疫","人工被动免疫","自然主动免疫","自然被动免疫","被动-主动免疫"],"a":3,"e":"胎儿经胎盘接受母体IgG抗体，属自然被动免疫，出生后6个月内对多种传染病有保护力。人工被动免疫为注射抗毒素或丙种球蛋白；自然主动免疫来自隐性感染或患病；人工主动免疫来自接种疫苗"},{"q":"狂犬病病毒疫苗属于","o":["减毒活疫苗","灭活疫苗","多价疫苗","亚单位疫苗","基因工程疫苗"],"a":1,"e":"狂犬病疫苗用细胞培养的病毒经灭活制成，失去感染性而保留抗原性，暴露后按程序接种。减毒活疫苗用于麻疹、脊髓灰质炎；多价疫苗指多个血清型；亚单位疫苗仅含保护性抗原蛋白；基因工程疫苗用于乙肝"},{"q":"我国研制并已应用的乙型肝炎疫苗属于","o":["减毒活疫苗","灭活疫苗","多价疫苗","亚单位疫苗","基因工程疫苗"],"a":4,"e":"我国乙肝疫苗为基因工程疫苗，用酵母菌或哺乳动物细胞表达重组HBsAg，纯化后制成，为世界首个基因工程疫苗。血源灭活疫苗已被替代；乙肝无减毒活疫苗；多价疫苗指覆盖多个血清型；亚单位疫苗不含核酸但制备路径不同"},{"q":"脊髓灰质炎糖丸属于","o":["减毒活疫苗","灭活疫苗","多价疫苗","亚单位疫苗","基因工程疫苗"],"a":0,"e":"脊髓灰质炎糖丸为口服减毒活疫苗，经肠道增殖，既诱生血清中和抗体又刺激局部sIgA。灭活疫苗为注射用Salk疫苗；多价疫苗指多个血清型；亚单位疫苗仅含抗原蛋白；基因工程疫苗用于乙肝"},{"q":"只能推算病毒颗粒数量的方法是","o":["红细胞凝集试验","蚀斑测定","光镜检测包涵体","中和试验","ID50或TCID50"],"a":1,"e":"蚀斑测定将病毒稀释后接种单层细胞，每个感染性病毒颗粒形成一个蚀斑，计数蚀斑可推算感染性病毒颗粒数量。红细胞凝集试验只反映血凝素效价；中和试验测抗体；ID50或TCID50测感染性滴度；光镜检测包涵体为定性"},{"q":"检测病毒感染性强弱的方法是","o":["红细胞凝集试验","蚀斑测定","光镜检测包涵体","中和试验","ID50或TCID50"],"a":4,"e":"TCID50或ID50以感染50%细胞或动物的最高稀释度为终点，反映病毒感染性强弱，数值越小毒力越强。蚀斑测定推算感染性颗粒数量；红细胞凝集试验测血凝素效价；中和试验测中和抗体；包涵体检测为形态学诊断"},{"q":"既能测定抗体又能鉴定病毒的方法是","o":["红细胞凝集试验","蚀斑测定","光镜检测包涵体","中和试验","ID50或TCID50"],"a":0,"e":"红细胞凝集试验利用病毒血凝素凝集红细胞，结合血凝抑制试验用已知抗体抑制凝集，既可测抗体又能鉴定病毒。蚀斑测定计数感染性颗粒；中和试验测抗体效价；ID50、TCID50测感染性滴度；包涵体检测为形态学观察"},{"q":"白色念珠菌常引起","o":["性病","脑膜炎","斑疹伤寒","癣病","多种内脏及皮肤、黏膜感染"],"a":4,"e":"白念珠菌为机会致病菌，机体抵抗力下降或菌群失调时引起皮肤、黏膜及内脏的急慢性感染，即念珠菌病。新型隐球菌主要引起脑膜炎；立克次体引起斑疹伤寒；皮肤癣菌引起癣病；淋病奈瑟菌等引起性病"},{"q":"立克次体常引起","o":["性病","脑膜炎","斑疹伤寒","癣病","多种内脏及皮肤、黏膜感染"],"a":2,"e":"立克次体是节肢动物传播的严格细胞内寄生菌，普氏和斑疹伤寒立克次体分别引起流行性与地方性斑疹伤寒。衣原体引起沙眼和性病；真菌引起癣病；隐球菌引起脑膜炎；白念珠菌引起皮肤黏膜及内脏感染"},{"q":"新型隐球菌常引起","o":["性病","脑膜炎","斑疹伤寒","癣病","多种内脏及皮肤、黏膜感染"],"a":1,"e":"新型隐球菌经呼吸道吸入，荚膜抗吞噬，最易侵犯中枢神经系统，引起亚急性或慢性脑膜炎，脑脊液墨汁染色可见厚荚膜。白念珠菌引起皮肤黏膜及内脏感染；立克次体引起斑疹伤寒；皮肤癣菌引起癣病"},{"q":"沙眼衣原体可引起","o":["性病","脑膜炎","斑疹伤寒","癣病","多种内脏及皮肤、黏膜感染"],"a":0,"e":"沙眼衣原体D至K型引起泌尿生殖道感染，L1至L3型引起性病淋巴肉芽肿，均属性传播疾病，包涵体结膜炎亦由其所致。淋病奈瑟菌也引起性病但非衣原体；立克次体引起斑疹伤寒；隐球菌引起脑膜炎"},{"q":"与细菌运动有关的细菌结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":1,"e":"鞭毛是细菌的运动器官，有鞭毛的细菌在液体中可主动游动，并有化学趋向性，如单鞭毛的霍乱弧菌每秒可移动55微米。荚膜抗吞噬；芽胞是休眠体；细胞壁维持形态；菌毛与黏附及接合有关，均无运动功能"},{"q":"作为高压蒸汽灭菌效果指标的是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":2,"e":"芽胞对热、干燥和消毒剂抵抗力极强，杀死芽胞是判断灭菌效果的指标，高压蒸汽灭菌以芽胞是否被杀灭为准，121℃15分钟可杀灭。荚膜与抗吞噬有关；鞭毛与运动有关；菌毛与黏附有关；细胞壁维持形态并提供内毒素"},{"q":"与细菌黏附或传递遗传物质有关的细菌结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":4,"e":"菌毛分普通菌毛和性菌毛，普通菌毛黏附宿主细胞，性菌毛在接合时传递质粒DNA。荚膜抗吞噬；鞭毛是运动器官；芽胞为休眠体；细胞壁维持形态并提供内毒素，均不承担黏附与遗传传递双重功能"},{"q":"具有抗吞噬作用的细菌结构是","o":["荚膜","鞭毛","芽胞","细胞壁","菌毛"],"a":0,"e":"荚膜多糖亲水带负电，与吞噬细胞膜静电排斥，阻滞表面吞噬，是肺炎链球菌、炭疽芽胞杆菌的重要毒力因子，失去荚膜则毒力显著减弱。鞭毛与运动有关；菌毛与黏附有关；芽胞为休眠体；细胞壁维持形态并含内毒素"},{"q":"莫氏立克次体的储存宿主是","o":["啮齿动物","家畜","幼猫","兔","患者"],"a":0,"e":"斑疹伤寒立克次体又称莫氏立克次体，储存宿主为啮齿类动物，经鼠蚤、鼠虱传播，引起地方性斑疹伤寒。普氏立克次体的储存宿主和传染源是患者；汉塞巴通体宿主为幼猫；贝纳柯克斯体宿主为牛、羊等家畜"},{"q":"普氏立克次体的储存宿主是","o":["啮齿动物","家畜","幼猫","兔","患者"],"a":4,"e":"普氏立克次体引起流行性斑疹伤寒，患者是储存宿主和传染源，人虱为传播媒介。斑疹伤寒立克次体储存宿主为啮齿动物；汉塞巴通体宿主为幼猫；贝纳柯克斯体宿主为家畜；森林脑炎病毒储存宿主为蝙蝠和啮齿类"},{"q":"汉塞巴通体的储存宿主是","o":["啮齿动物","家畜","幼猫","兔","患者"],"a":2,"e":"汉塞巴通体主要宿主是猫，尤其幼猫，其口腔和咽部带菌，经咬伤、抓伤传播，引起猫抓病，表现为局部淋巴结肿大，病人多为儿童。普氏立克次体储存宿主为患者；斑疹伤寒立克次体为啮齿动物；贝纳柯克斯体为家畜"},{"q":"结核分枝杆菌的生长特点是","o":["固体培养基中形成菜花样菌落","胆盐能够促进菌体自溶","能够合成绿色水溶性色素","不能在无生命的人工培养基上生长","半固体培养基接种穿刺线会变模糊"],"a":0,"e":"结核分枝杆菌菌落干燥、坚硬、表面颗粒状、乳酪色，形似菜花样，因含大量脂质而生长缓慢。沙门菌在SS平板形成无色透明菌落；肺炎链球菌菌落细小、中央脐状；白喉棒状杆菌形成灰白色小菌落；均非菜花样"},{"q":"沙门菌属中细菌的生长特点是","o":["固体培养基中形成菜花样菌落","胆盐能够促进菌体自溶","能够合成绿色水溶性色素","不能在无生命的人工培养基上生长","半固体培养基接种穿刺线会变模糊"],"a":4,"e":"沙门菌属多数有周鞭毛，半固体培养基穿刺线呈羽毛状或云雾状混浊，动力阳性，是肠道杆菌鉴别的常用项目。结核分枝杆菌无鞭毛、穿刺线清晰；肺炎链球菌无鞭毛；志贺菌无鞭毛、穿刺线清晰不扩散"},{"q":"肺炎链球菌的生长特点是","o":["固体培养基中形成菜花样菌落","胆盐能够促进菌体自溶","能够合成绿色水溶性色素","不能在无生命的人工培养基上生长","半固体培养基接种穿刺线会变模糊"],"a":1,"e":"肺炎链球菌产生自溶酶，可被胆汁或胆盐激活，胆汁溶菌试验阳性，菌落中央下陷呈脐状。甲型溶血性链球菌胆汁溶菌阴性；结核分枝杆菌菌落菜花样；沙门菌有鞭毛使穿刺线模糊；均无胆盐激活的自溶酶"},{"q":"潜伏于三叉神经节的是","o":["水痘带状疱疹病毒","单纯疱疹病毒1型","单纯疱疹病毒2型","人巨细胞病毒","EB病毒"],"a":1,"e":"HSV-1原发感染后潜伏于三叉神经节和颈上神经节，再激活引起唇疱疹、角膜炎。HSV-2潜伏骶神经节；VZV潜伏脊髓后根神经节；HCMV潜伏腺组织、肾脏和白细胞；EBV潜伏B淋巴细胞"},{"q":"潜伏于骶神经节的是","o":["水痘带状疱疹病毒","单纯疱疹病毒1型","单纯疱疹病毒2型","人巨细胞病毒","EB病毒"],"a":2,"e":"HSV-2主要经性接触传播，原发感染后潜伏于骶神经节，再激活引起生殖器疱疹，亦可经产道感染新生儿。HSV-1潜伏三叉神经节；VZV潜伏脊髓后根神经节；HCMV潜伏腺组织和白细胞；EBV潜伏B淋巴细胞"},{"q":"潜伏于脊髓后根神经节的是","o":["水痘带状疱疹病毒","单纯疱疹病毒1型","单纯疱疹病毒2型","人巨细胞病毒","EB病毒"],"a":0,"e":"VZV原发感染引起水痘，病愈后潜伏于脊髓后根神经节或脑神经感觉神经节，再激活引起带状疱疹。HSV-1潜伏三叉神经节；HSV-2潜伏骶神经节；HCMV潜伏腺组织和白细胞；EBV潜伏B淋巴细胞"},{"q":"血清中不易检测到的成分是","o":["抗-HBs","抗-HBc","HBsAg","HBcAg","HBeAg"],"a":3,"e":"HBcAg是衣壳蛋白，组装后包裹病毒基因组，一般不以游离形式存在于血液，故血清中不易检出。HBsAg大量存在于血中；HBeAg可游离于血清；抗-HBs、抗-HBc均为抗体，检测容易"},{"q":"对机体有保护性的成分是","o":["抗-HBs","抗-HBc","HBsAg","HBcAg","HBeAg"],"a":0,"e":"抗-HBs是HBV特异性中和抗体，出现于恢复期、既往感染或接种疫苗后，表示机体有免疫力。抗-HBc无保护作用，IgM提示近期感染；HBsAg是感染标志；HBeAg提示复制活跃；HBcAg为衣壳抗原"},{"q":"存在于Dane颗粒表面的成分是","o":["抗-HBs","抗-HBc","HBsAg","HBcAg","HBeAg"],"a":2,"e":"Dane颗粒即完整HBV，外层包膜含HBsAg，故其表面成分为HBsAg，该抗原大量游离于感染者血液。HBcAg位于核衣壳内层；HBeAg是可溶性蛋白；抗-HBs、抗-HBc为抗体，不存在于病毒颗粒表面"},{"q":"细菌生长曲线中，具有典型细菌特征的是在","o":["迟缓期","对数期","稳定期","衰亡期","增殖期"],"a":1,"e":"对数期细菌以恒定几何级数分裂，菌体形态、染色性和生理活性最典型，是观察形态和测定生物学性状的适宜阶段。迟缓期菌体增大但分裂极少，稳定期活菌数恒定并开始合成芽胞与外毒素，衰亡期菌体变形自溶"},{"q":"细菌变异多发生在","o":["迟缓期","对数期","稳定期","衰亡期","增殖期"],"a":3,"e":"衰亡期细菌繁殖停止、死亡数超过活菌数，形态显著改变，出现衰退型，代谢趋于停滞，变异多在此期发生。稳定期活菌数恒定，外毒素、芽胞产生多；对数期形态典型、代谢旺盛；迟缓期菌体增大但未分裂"},{"q":"细菌的外毒素等代谢产物多产生在","o":["迟缓期","对数期","稳定期","衰亡期","增殖期"],"a":2,"e":"稳定期营养物质消耗、代谢产物积聚，繁殖与死亡大致平衡，芽胞、外毒素和抗生素等次级代谢产物多在此期产生。对数期细菌大量繁殖但产物少；衰亡期菌体自溶；迟缓期合成酶系和能量，尚不产毒"},{"q":"自病人体内分离流行性出血热病毒最好取","o":["咽漱液","粪便","尿","脑组织","血液"],"a":4,"e":"汉坦病毒在发热期病毒血症明显，血液中含毒量高，取血液分离阳性率高，是流行性出血热病原学诊断的常用标本。咽漱液用于流感；粪便用于轮状病毒；尿虽可排毒但分离率低；脑组织用于狂犬病病毒"},{"q":"分离狂犬病病毒应取","o":["咽漱液","粪便","尿","脑组织","血液"],"a":3,"e":"狂犬病病毒在中枢神经组织含量高，取脑组织悬液接种小鼠颅内分离，脑组织切片查内氏小体可确诊，唾液和角膜印片亦可检测抗原。咽漱液用于流感；粪便用于轮状病毒；尿用于汉坦病毒；血液分离率低于脑组织"},{"q":"分离脊髓灰质炎病毒最好取","o":["咽漱液","粪便","尿","脑组织","血液"],"a":1,"e":"脊髓灰质炎病毒经粪-口途径传播，在肠道增殖并随粪便排出，故取粪便或肛拭子分离阳性率最高，发病早期采集更佳。咽漱液用于流感；尿用于汉坦病毒；脑组织用于狂犬病；血液仅在病毒血症期可检出"},{"q":"Q热的病原体是","o":["普氏立克次体","恙虫病立克次体","斑疹伤寒立克次体","森林脑炎病毒","贝纳柯克斯体"],"a":4,"e":"贝纳柯克斯体又称Q热柯克斯体，是Q热的病原体，经蜱传播，耐热，需100℃至少10分钟才被杀灭。普氏立克次体引起流行性斑疹伤寒；恙虫病东方体引起恙虫病；斑疹伤寒立克次体引起地方性斑疹伤寒"},{"q":"鼠型斑疹伤寒病原体是","o":["普氏立克次体","恙虫病立克次体","斑疹伤寒立克次体","森林脑炎病毒","贝纳柯克斯体"],"a":2,"e":"斑疹伤寒立克次体又称莫氏立克次体，经鼠蚤传播，引起地方性斑疹伤寒，即鼠型斑疹伤寒。普氏立克次体引起流行性斑疹伤寒；恙虫病东方体引起恙虫病；贝纳柯克斯体引起Q热；森林脑炎病毒引起森林脑炎"},{"q":"地方性斑疹伤寒病原体是","o":["普氏立克次体","恙虫病立克次体","斑疹伤寒立克次体","森林脑炎病毒","贝纳柯克斯体"],"a":2,"e":"地方性斑疹伤寒由斑疹伤寒立克次体引起，鼠蚤为媒介，临床有发热、头痛、红疹三联征，病情较流行性斑疹伤寒轻。普氏立克次体引起流行性斑疹伤寒，人虱传播；恙虫病东方体引起恙虫病；贝纳柯克斯体引起Q热"},{"q":"能引起腹泻，65℃30分钟可被破坏的致病物质是","o":["不耐热肠毒素","耐热肠毒素","志贺毒素","定植因子","脂多糖"],"a":0,"e":"ETEC产生不耐热肠毒素LT，65℃30分钟即被破坏，激活腺苷环化酶使cAMP升高，引起水样腹泻。耐热肠毒素ST耐100℃、激活鸟苷环化酶；志贺毒素抑制蛋白合成；定植因子介导黏附；脂多糖为内毒素"},{"q":"能引起体温持续升高的致病物质是","o":["不耐热肠毒素","耐热肠毒素","志贺毒素","定植因子","脂多糖"],"a":4,"e":"脂多糖即内毒素，作用于单核巨噬细胞释放内源性致热原，引起体温持续升高，并可致白细胞增多、微循环障碍和休克。不耐热肠毒素与耐热肠毒素均引起腹泻；志贺毒素致细胞损伤；定植因子仅介导黏附"},{"q":"能黏附于肠道黏膜的致病物质是","o":["不耐热肠毒素","耐热肠毒素","志贺毒素","定植因子","脂多糖"],"a":3,"e":"定植因子CFA是ETEC的特殊菌毛，黏附于小肠黏膜上皮细胞，使细菌定居并繁殖，编码基因位于质粒。不耐热肠毒素和耐热肠毒素引起腹泻；志贺毒素抑制蛋白合成；脂多糖为内毒素，均无黏附作用"},{"q":"杀灭细菌芽孢的方法是","o":["灭菌","消毒","防腐","清洁","无菌"],"a":0,"e":"灭菌是杀灭物体上包括芽胞在内的全部微生物，杀死芽胞是判断灭菌效果的指标。消毒只杀灭病原微生物，不保证杀死芽胞；防腐为抑制微生物生长；清洁为减少微生物数量；无菌是不存在活菌的状态"},{"q":"只杀灭细菌繁殖体的方法是","o":["灭菌","消毒","防腐","清洁","无菌"],"a":1,"e":"消毒是杀灭物体上病原微生物的方法，通常只能杀死繁殖体，不能杀死细菌芽胞，故不保证灭菌效果。灭菌要求杀死包括芽胞在内的全部微生物；防腐为抑菌；清洁为去除污物；无菌为不存在活菌的状态"},{"q":"除去一切污秽以减少微生物数量的方法是","o":["灭菌","消毒","防腐","清洁","无菌"],"a":3,"e":"清洁通过除去尘埃和一切污秽减少微生物数量，如冲洗、擦拭，是物品消毒、灭菌前必须经过的卫生处理，可提高后续效果。灭菌杀死全部微生物包括芽胞；消毒杀灭病原微生物；防腐抑制微生物生长；无菌为无活菌状态"},{"q":"甲型溶血性链球菌与肺炎链球菌相同的性状是","o":["产生IgA1蛋白酶，破坏黏膜表面IgA","一般不发酵菊糖，不被胆汁溶解","能产生自溶酶，并可被胆汁激活","血平板上形成完全透明的溶血环","血平板上形成半透明不完全溶血环"],"a":4,"e":"甲型溶血性链球菌与肺炎链球菌在血平板上均形成草绿色半透明溶血环，即α溶血。肺炎链球菌胆汁溶菌阳性、自溶酶可被胆盐激活，甲型溶血性链球菌阴性；乙型溶血性链球菌形成完全透明溶血环；产IgA1蛋白酶者为A群链球菌"},{"q":"链球菌属细菌共同的生物学性状是","o":["产生IgA1蛋白酶，破坏黏膜表面IgA","一般不发酵菊糖，不被胆汁溶解","能产生自溶酶，并可被胆汁激活","血平板上形成完全透明的溶血环","血平板上形成半透明不完全溶血环"],"a":1,"e":"链球菌属一般不分解菊糖、不被胆汁溶解，借此与肺炎链球菌区别。肺炎链球菌分解菊糖、胆汁溶菌阳性；A群链球菌产生IgA1蛋白酶；乙型溶血性链球菌形成完全透明溶血环；α溶血为甲型链球菌和肺炎链球菌共有"},{"q":"乙型溶血性链球菌不同于其他链球菌的特点是","o":["产生IgA1蛋白酶，破坏黏膜表面IgA","一般不发酵菊糖，不被胆汁溶解","能产生自溶酶，并可被胆汁激活","血平板上形成完全透明的溶血环","血平板上形成半透明不完全溶血环"],"a":3,"e":"乙型溶血性链球菌在血平板上形成2至4毫米宽、界限分明、完全透明的溶血环，红细胞完全溶解。甲型溶血性链球菌与肺炎链球菌为半透明草绿色溶血；A群链球菌一般不分解菊糖；自溶酶被胆汁激活者为肺炎链球菌"},{"q":"可产生自溶酶的化脓性球菌是","o":["淋病奈瑟菌","脑膜炎奈瑟菌","A群链球菌","金黄色葡萄球菌","流感嗜血杆菌"],"a":1,"e":"脑膜炎奈瑟菌可产生自溶酶，菌体易自溶，故标本须及时送检并保温接种。淋病奈瑟菌同属奈瑟菌属但主要引起泌尿生殖道化脓性感染；A群链球菌产生链球菌溶素；金黄色葡萄球菌产生凝固酶；流感嗜血杆菌生长需Ⅹ、Ⅴ因子"},{"q":"可经性接触传播的病原体是","o":["淋病奈瑟菌","脑膜炎奈瑟菌","A群链球菌","金黄色葡萄球菌","流感嗜血杆菌"],"a":0,"e":"淋病奈瑟菌是人类淋病病原体，主要经性接触直接传播，引起泌尿生殖道黏膜化脓性感染。脑膜炎奈瑟菌经呼吸道飞沫传播；A群链球菌经接触和飞沫传播；金黄色葡萄球菌经接触传播；流感嗜血杆菌经呼吸道传播"},{"q":"引起新生儿“脓漏眼”的病原体是","o":["淋病奈瑟菌","脑膜炎奈瑟菌","A群链球菌","金黄色葡萄球菌","流感嗜血杆菌"],"a":0,"e":"淋病奈瑟菌可经产道感染新生儿，引起淋菌性结膜炎，即脓漏眼，可致盲。脑膜炎奈瑟菌引起流行性脑脊髓膜炎；A群链球菌引起咽炎和猩红热；金黄色葡萄球菌引起化脓性感染；流感嗜血杆菌引起中耳炎和脑膜炎"},{"q":"肺炎链球菌由粗糙型转变成光滑型的转移方式是","o":["基因突变","转化","接合","转导","溶原性转换"],"a":1,"e":"肺炎链球菌由粗糙型转为光滑型，是受体菌摄取供体菌游离DNA并整合，即转化，1928年由Griffith首先发现。接合需性菌毛；转导经噬菌体介导；溶原性转换由前噬菌体基因编码性状；基因突变为自身序列改变"},{"q":"白喉棒状杆菌由无毒株转变为有毒株是由于发生了","o":["基因突变","转化","接合","转导","溶原性转换"],"a":4,"e":"白喉棒状杆菌无毒株携带β-棒状杆菌噬菌体后，tox基因整合于宿主基因组，获得产毒能力，属溶原性转换。转化是摄取游离DNA；接合经性菌毛传递质粒；转导为噬菌体介导的DNA转移；基因突变不引入新基因"},{"q":"R质粒在不同细菌间传递是通过","o":["基因突变","转化","接合","转导","溶原性转换"],"a":2,"e":"R质粒为接合性耐药质粒，经性菌毛在细菌间传递，是耐药性迅速扩散的主要原因。转化是摄取游离DNA；转导经噬菌体传递；溶原性转换由前噬菌体使细菌获得新性状；基因突变仅改变自身基因序列"},{"q":"以人名命名的微生物是","o":["巴兴体","立克次体","支原体","衣原体","螺旋体"],"a":1,"e":"立克次体为纪念因研究斑疹伤寒而感染献身的Howard Taylor Ricketts而得名，是一类以节肢动物为媒介、严格细胞内寄生的细菌。支原体、衣原体、螺旋体均按形态或结构特点命名"},{"q":"细胞壁不具有肽聚糖的是","o":["巴兴体","立克次体","支原体","衣原体","螺旋体"],"a":3,"e":"衣原体细胞壁含外膜但缺乏肽聚糖，其结构靠外膜蛋白二硫键交联维持，故β-内酰胺类对其无效，细胞内以原体和网状体交替发育。支原体根本无细胞壁；立克次体、螺旋体、巴通体细胞壁均含肽聚糖"},{"q":"缺乏细胞壁的是","o":["巴兴体","立克次体","支原体","衣原体","螺旋体"],"a":2,"e":"支原体无细胞壁，仅由含胆固醇的细胞膜包被，呈高度多形性，能通过滤菌器，对β-内酰胺类天然耐药，培养需血清，菌落呈油煎蛋样。衣原体有细胞壁但缺肽聚糖；立克次体、螺旋体、巴通体均有细胞壁"},{"q":"利福霉素类、磺胺类及喹诺酮类等的抗菌作用机制是","o":["抑制细胞壁合成","损伤细胞膜功能","抑制菌体蛋白合成","抑制核酸的合成","抑制逆转录酶活性"],"a":3,"e":"利福霉素抑制RNA聚合酶阻断转录，喹诺酮类抑制DNA旋转酶，磺胺类竞争二氢叶酸合成酶影响核酸合成，三者均干扰核酸与叶酸代谢。β-内酰胺类抑制细胞壁合成；多黏菌素损伤细胞膜；氨基糖苷类抑制蛋白合成"},{"q":"四环素类、氯霉素类及氨基糖苷类等的抗菌作用机制是","o":["抑制细胞壁合成","损伤细胞膜功能","抑制菌体蛋白合成","抑制核酸的合成","抑制逆转录酶活性"],"a":2,"e":"四环素类作用于30S亚基，氯霉素、红霉素作用于50S亚基，氨基糖苷类作用于30S亚基，均阻断细菌蛋白质合成。β-内酰胺类抑制细胞壁合成；多黏菌素损伤细胞膜；喹诺酮类抑制DNA旋转酶；利福平抑制转录"},{"q":"β-内酰胺类（β-lactams）包括青霉素类和头孢菌素类等的抗菌作用机制是","o":["抑制细胞壁合成","损伤细胞膜功能","抑制菌体蛋白合成","抑制核酸的合成","抑制逆转录酶活性"],"a":0,"e":"β-内酰胺类与青霉素结合蛋白即转肽酶结合，阻断肽聚糖交联，使细胞壁缺损、细菌在低渗环境中裂解。氨基糖苷类抑制蛋白合成；多黏菌素损伤细胞膜；喹诺酮类抑制DNA旋转酶；磺胺类干扰叶酸代谢"},{"q":"乙脑病毒","o":["性接触传播","以节肢动物为媒介传播","呼吸道传播","消化道传播","眼-眼或眼-手-眼传播"],"a":1,"e":"乙脑病毒属虫媒病毒，以三带喙库蚊为媒介叮咬传播，蚊兼作储存宿主，猪为扩增宿主，人感染后为终末宿主。解脲脲原体经性接触传播；肺炎衣原体经呼吸道传播；甲肝、戊肝经消化道传播；腺病毒可经眼-手-眼传播"},{"q":"解脲脲原体","o":["性接触传播","以节肢动物为媒介传播","呼吸道传播","消化道传播","眼-眼或眼-手-眼传播"],"a":0,"e":"解脲脲原体定植泌尿生殖道，经性接触传播，也可经母婴传播，引起非淋菌性尿道炎、宫颈炎，性活跃人群感染率高。肺炎衣原体经呼吸道；乙脑病毒经蚊媒；甲肝经消化道；腺病毒经眼结膜或手眼接触传播"},{"q":"肺炎衣原体","o":["性接触传播","以节肢动物为媒介传播","呼吸道传播","消化道传播","眼-眼或眼-手-眼传播"],"a":2,"e":"肺炎衣原体经呼吸道飞沫传播，引起咽炎、支气管炎和肺炎，人类是其唯一宿主，感染后血清抗体可长期存在。解脲脲原体经性接触；乙脑病毒经蚊媒；甲肝、戊肝经消化道；腺病毒经眼-手-眼途径"},{"q":"诊断肠热症的方法是","o":["OT试验","肥达试验","IMViC试验","锡克试验","Elek平板毒力试验"],"a":1,"e":"肥达试验用伤寒沙门菌O、H抗原及副伤寒甲、乙、丙H抗原与血清凝集，测定抗体效价，协助诊断肠热症。OT试验测结核感染；锡克试验测白喉免疫；IMViC试验鉴定大肠埃希菌；Elek平板测白喉毒素毒力"},{"q":"检测有无白喉抗毒素免疫的方法是","o":["OT试验","肥达试验","IMViC试验","锡克试验","Elek平板毒力试验"],"a":3,"e":"锡克试验皮内注射白喉毒素，局部红肿为阳性，表示体内无足够抗毒素、易感；阴性表示有免疫力。OT试验测结核分枝杆菌感染；肥达试验诊断肠热症；IMViC鉴定肠道杆菌；Elek平板检测产毒株"},{"q":"测定机体对结核分枝杆菌有无免疫力的方法是","o":["OT试验","肥达试验","IMViC试验","锡克试验","Elek平板毒力试验"],"a":0,"e":"OT试验即结核菌素试验，注入结核菌素后观察迟发型超敏反应，阳性表示已感染并产生细胞免疫，用于判断有无免疫力。肥达试验诊断肠热症；锡克试验测白喉免疫；IMViC鉴定大肠埃希菌；Elek平板测毒素"},{"q":"破伤风梭菌产生","o":["无芽孢厌氧菌","产气荚膜梭菌","痉挛毒素","肉毒毒素","艰难梭菌"],"a":2,"e":"破伤风梭菌在厌氧伤口繁殖，产生破伤风痉挛毒素，阻止抑制性神经递质释放，引起肌肉强直性痉挛。肉毒梭菌产生肉毒毒素；产气荚膜梭菌产生α毒素等；艰难梭菌产生毒素A、B；无芽胞厌氧菌不产此毒素"},{"q":"引起伪膜性肠炎的细菌是","o":["无芽孢厌氧菌","产气荚膜梭菌","痉挛毒素","肉毒毒素","艰难梭菌"],"a":4,"e":"艰难梭菌在抗生素致菌群失调后过度繁殖，产生毒素A和毒素B，毒素A为肠毒素，引起假膜性结肠炎，是医源性腹泻最重要的病原体。产气荚膜梭菌引起气性坏疽；破伤风梭菌产生痉挛毒素；肉毒梭菌产生肉毒毒素"},{"q":"肉毒梭菌产生","o":["无芽孢厌氧菌","产气荚膜梭菌","痉挛毒素","肉毒毒素","艰难梭菌"],"a":3,"e":"肉毒梭菌产生肉毒毒素，抑制胆碱能神经末梢释放乙酰胆碱，引起弛缓性麻痹，是已知最剧烈的毒物。破伤风梭菌产生痉挛毒素，引起强直性痉挛；产气荚膜梭菌产生α毒素致气性坏疽；艰难梭菌产生毒素A、B"},{"q":"对甲型流感病毒有效的药物是","o":["金刚烷胺","IFN诱生剂","IFN","阿糖腺苷","阿昔洛韦"],"a":0,"e":"金刚烷胺阻断M2蛋白离子通道，抑制甲型流感病毒脱壳，用于甲流的预防和早期治疗。阿昔洛韦抗疱疹病毒；阿糖腺苷抗疱疹和乙肝病毒；IFN为广谱抗病毒蛋白；IFN诱生剂仅间接诱导干扰素产生"},{"q":"对单纯疱疹病毒有效的药物是","o":["金刚烷胺","IFN诱生剂","IFN","阿糖腺苷","阿昔洛韦"],"a":4,"e":"阿昔洛韦是鸟嘌呤核苷类似物，在疱疹病毒胸苷激酶作用下活化，抑制病毒DNA聚合酶，对HSV疗效好。金刚烷胺仅对甲流有效；阿糖腺苷用于疱疹病毒但毒性较大；IFN为宿主细胞产生的抗病毒蛋白"},{"q":"由细胞产生的抗病毒药物是","o":["金刚烷胺","IFN诱生剂","IFN","阿糖腺苷","阿昔洛韦"],"a":2,"e":"干扰素由宿主细胞受病毒诱导后产生，不直接杀伤病毒，而通过抑制病毒蛋白表达发挥抗病毒作用，并有种属特异性。金刚烷胺为合成化学药；阿糖腺苷和阿昔洛韦为核苷类似物；IFN诱生剂只是诱导干扰素产生的物质"},{"q":"自然主动免疫包括","o":["隐性感染","注射IFN","注射TAT","喂初乳","接种BCG"],"a":0,"e":"隐性感染后机体获得特异性免疫力，由自身免疫系统产生，属自然主动免疫，病后获得的免疫同样归入此类。注射IFN、TAT属人工被动免疫；喂初乳属自然被动免疫；接种BCG属人工主动免疫"},{"q":"自然被动免疫包括","o":["隐性感染","注射IFN","注射TAT","喂初乳","接种BCG"],"a":3,"e":"初乳含母体分泌型IgA和IgG，婴儿经消化道获得，胎盘转运IgG亦属此列，均为自然被动免疫，维持时间较短。隐性感染为自然主动免疫；注射IFN和TAT为人工被动免疫；接种BCG为人工主动免疫"},{"q":"人工主动免疫包括","o":["隐性感染","注射IFN","注射TAT","喂初乳","接种BCG"],"a":4,"e":"接种BCG使机体自身产生免疫应答，属人工主动免疫，需接种1至3次，免疫力出现慢但维持较久，可达数月至数年。隐性感染为自然主动免疫；注射IFN、TAT为人工被动免疫；喂初乳为自然被动免疫"},{"q":"协助诊断伤寒可用","o":["ASO试验","外斐反应","Dick试验","锡克试验","肥达试验"],"a":4,"e":"肥达试验检测伤寒沙门菌O、H抗体及副伤寒甲、乙、丙H抗体，协助诊断伤寒和副伤寒，需双份血清对比。ASO试验用于风湿热；外斐反应用于斑疹伤寒等立克次体病；Dick试验测猩红热易感性；锡克试验测白喉免疫"},{"q":"协助诊断斑疹伤寒可用","o":["ASO试验","外斐反应","Dick试验","锡克试验","肥达试验"],"a":1,"e":"外斐反应用变形杆菌OX19、OX2、OXk菌株的O抗原与病人血清凝集，辅助诊断斑疹伤寒等立克次体病。肥达试验诊断肠热症；ASO试验诊断风湿热；Dick试验测猩红热；锡克试验测白喉免疫"},{"q":"协助诊断风湿热用","o":["ASO试验","外斐反应","Dick试验","锡克试验","肥达试验"],"a":0,"e":"ASO试验检测抗链球菌溶血素O抗体，风湿热病人效价显著升高，活动期常超过400单位，有辅助诊断意义。肥达试验诊断肠热症；外斐反应诊断立克次体病；Dick试验测猩红热；锡克试验测白喉免疫"},{"q":"破伤风痉挛毒素致病机制是","o":["破坏细胞膜使细胞裂解","抑制易感细胞的蛋白质合成","阻断上、下神经元之间抑制性介质的传递，导致肌肉痉挛","抑制神经末梢释放乙酰胆碱，影响神经冲动的传递，导致肌肉弛缓型麻痹","激活细胞内腺苷环化酶，使cAMP的水平增高，使黏膜细胞的分泌功能增强"],"a":2,"e":"破伤风痉挛毒素经轴突逆行至脊髓前角，轻链破坏突触小泡膜蛋白，阻止抑制性神经递质释放，运动神经元失去抑制而强直痉挛。肉毒毒素抑制乙酰胆碱释放致弛缓性麻痹；白喉毒素抑制蛋白合成；霍乱毒素激活腺苷环化酶"},{"q":"肉毒毒素机制是","o":["破坏细胞膜使细胞裂解","抑制易感细胞的蛋白质合成","阻断上、下神经元之间抑制性介质的传递，导致肌肉痉挛","抑制神经末梢释放乙酰胆碱，影响神经冲动的传递，导致肌肉弛缓型麻痹","激活细胞内腺苷环化酶，使cAMP的水平增高，使黏膜细胞的分泌功能增强"],"a":3,"e":"肉毒毒素作用于神经肌肉接头，轻链灭活突触小泡膜蛋白，抑制乙酰胆碱释放，导致弛缓性麻痹。破伤风痉挛毒素阻断抑制性介质释放致痉挛；白喉毒素抑制蛋白合成；霍乱毒素升高cAMP；链球菌溶素破坏细胞膜"},{"q":"白喉毒素致病机制是","o":["破坏细胞膜使细胞裂解","抑制易感细胞的蛋白质合成","阻断上、下神经元之间抑制性介质的传递，导致肌肉痉挛","抑制神经末梢释放乙酰胆碱，影响神经冲动的传递，导致肌肉弛缓型麻痹","激活细胞内腺苷环化酶，使cAMP的水平增高，使黏膜细胞的分泌功能增强"],"a":1,"e":"白喉毒素A链催化ADP-核糖基转移至延伸因子EF-2，使其失活，抑制易感细胞蛋白质合成。破伤风毒素阻断抑制性介质释放；肉毒毒素抑制乙酰胆碱释放；霍乱毒素激活腺苷环化酶；链球菌溶素破坏细胞膜"},{"q":"其基因组最小的病毒是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":3,"e":"HDV基因组为单负链环状RNA，仅1.7kb，是五种肝炎病毒中最小的，且为缺陷病毒，需HBV提供包膜。HBV为3.2kbp DNA；HAV为7.5kb RNA；HCV为9.5kb RNA；HEV为7.2kb RNA"},{"q":"属于缺陷病毒的是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":3,"e":"HDV为缺陷病毒，基因组仅1.7kb，不能独立复制，须由HBV提供HBsAg作包膜才能装配子代，故其感染必伴HBV感染。HAV、HEV可独立感染；HBV、HCV基因组完整，均不需辅助病毒"},{"q":"属于DNA病毒的是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":1,"e":"HBV属嗜肝DNA病毒科，基因组为部分双链环状DNA，约3.2kbp，是五种肝炎病毒中唯一的DNA病毒。HAV、HCV、HDV、HEV均为RNA病毒，其中HDV为单负链环状RNA，HCV与黄病毒同科"},{"q":"属于中效消毒剂的组合是","o":["过氧化氢-季铵盐类-氯己定","次氯酸钠-过氧乙酸-漂白粉","氯己定-高锰酸钾-季铵盐类","戊二醛-环氧乙烷-碘伏","乙醇-碘附-异丙醇"],"a":4,"e":"中效消毒剂可杀灭细菌繁殖体、结核分枝杆菌、真菌和多数病毒，但不能杀灭芽胞，乙醇、碘附、异丙醇属此类，碘附为含碘消毒剂。过氧乙酸、含氯消毒剂为高效；氯己定为低效；戊二醛、环氧乙烷为灭菌剂"},{"q":"属于高效消毒剂的组合是","o":["过氧化氢-季铵盐类-氯己定","次氯酸钠-过氧乙酸-漂白粉","氯己定-高锰酸钾-季铵盐类","戊二醛-环氧乙烷-碘伏","乙醇-碘附-异丙醇"],"a":1,"e":"高效消毒剂可杀灭一切繁殖体（含结核分枝杆菌）、真菌、病毒及部分芽胞，含氯制剂、过氧乙酸、过氧化氢、戊二醛、环氧乙烷均属此级；次氯酸钠与漂白粉靠有效氯氧化菌体—SH基，过氧乙酸靠强氧化作用。A项实为过氧化氢高效而季铵盐类、氯己定低效的混配；D项碘伏属中效，与戊二醛、环氧乙烷不属同级；E项乙醇、碘附、异丙醇同为中效，不能杀灭芽胞。C项三者皆为低效"},{"q":"属于低效消毒剂的组合是","o":["过氧化氢-季铵盐类-氯己定","次氯酸钠-过氧乙酸-漂白粉","氯己定-高锰酸钾-季铵盐类","戊二醛-环氧乙烷-碘伏","乙醇-碘附-异丙醇"],"a":2,"e":"低效消毒剂只能杀灭细菌繁殖体，对结核分枝杆菌、亲水病毒和芽胞无效，氯己定、季铵盐类（苯扎溴铵）、高锰酸钾均属此级；季铵盐为阳离子表面活性剂，吸附菌体后改变胞壁通透性，使酶与代谢中间产物外逸。A项中过氧化氢属高效，混入后不能整体判为低效；B项含氯制剂与过氧乙酸均为高效；D项戊二醛、环氧乙烷高效而碘伏中效；E项乙醇、碘附、异丙醇为中效"}];
